-- ----------------------------
-- Table structure for lkt_activity
-- ----------------------------
DROP TABLE IF EXISTS `lkt_activity`;
CREATE TABLE `lkt_activity` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `activity_type` tinyint(2) NOT NULL DEFAULT '1' COMMENT '类型 0.活动专题 1.营销插件',
  `plug_type` tinyint(2) NOT NULL DEFAULT '1' COMMENT '插件类型 ',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subtitle` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_image` tinyint(2) DEFAULT '0' COMMENT '是否有宣传图 0.没有宣传图 1.有宣传图',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `p_id` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_display` tinyint(2) NOT NULL DEFAULT '0' COMMENT '是否显示 0.不显示 1.显示',
  `sort` int(11) DEFAULT '100' COMMENT '排序',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `subtraction_id` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='活动表';

-- ----------------------------
-- Records of lkt_activity
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_activity_pro
-- ----------------------------
DROP TABLE IF EXISTS `lkt_activity_pro`;
CREATE TABLE `lkt_activity_pro` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `activity_id` int(11) NOT NULL DEFAULT '0' COMMENT '活动ID',
  `p_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品ID',
  `is_display` tinyint(2) NOT NULL DEFAULT '0' COMMENT '是否显示 0.不显示 1.显示',
  `sort` int(11) DEFAULT '100' COMMENT '排序',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=196 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='活动商品表';

-- ----------------------------
-- Records of lkt_activity_pro
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_admin
-- ----------------------------
DROP TABLE IF EXISTS `lkt_admin`;
CREATE TABLE `lkt_admin` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `sid` int(11) NOT NULL DEFAULT '0' COMMENT '上级id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `password` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `admin_type` int(11) DEFAULT '1' COMMENT '管理类型 0=平台管理员',
  `permission` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `role` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` int(11) DEFAULT '0' COMMENT '类型 0:系统管理员 1：客户 2:商城管理员 3:店主',
  `store_id` int(11) DEFAULT '0' COMMENT '商城id',
  `shop_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `status` int(11) NOT NULL DEFAULT '2' COMMENT '状态 1:禁用 2：启用',
  `portrait` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `nickname` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `birthday` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sex` int(2) DEFAULT '1' COMMENT '性别（1 男  2 女）',
  `tel` varchar(22) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `token` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `ip` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `recycle` tinyint(2) DEFAULT NULL COMMENT '回收站 0:不回收 1:回收 ',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `login_num` int(11) NOT NULL DEFAULT '0' COMMENT '登录次数',
  `lang` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=765 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='管理员表';

-- ----------------------------
-- Records of lkt_admin
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_admin_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_admin_record`;
CREATE TABLE `lkt_admin_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) DEFAULT '0' COMMENT '商城id',
  `admin_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `event` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` tinyint(4) DEFAULT NULL COMMENT '类型 0:登录/退出 1:添加 2:修改 3:删除 4:导出 5:启用/禁用 6:通过/拒绝 10删除订单',
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `source` int(11) NOT NULL DEFAULT '1' COMMENT '数据来源 1.管理平台  2.PC店铺',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺id',
  `operator_id` int(11) DEFAULT '0' COMMENT '操作人ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7910 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='管理员记录表';

-- ----------------------------
-- Records of lkt_admin_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_agreement
-- ----------------------------
DROP TABLE IF EXISTS `lkt_agreement`;
CREATE TABLE `lkt_agreement` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `name` char(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '类型 0:注册 1:店铺 2.隐私 3.会员 4.供应商',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `modify_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='协议表';

-- ----------------------------
-- Records of lkt_agreement
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_article
-- ----------------------------
DROP TABLE IF EXISTS `lkt_article`;
CREATE TABLE `lkt_article` (
  `Article_id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '文章id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `Article_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Article_prompt` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Article_imgurl` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `share_num` int(11) NOT NULL DEFAULT '0' COMMENT '分享次数',
  `total_amount` decimal(12,2) NOT NULL COMMENT '红包总金额',
  `total_num` int(11) NOT NULL DEFAULT '0' COMMENT '红包个数',
  `wishing` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`Article_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='单篇文章表';

-- ----------------------------
-- Records of lkt_article
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_auction_collection
-- ----------------------------
DROP TABLE IF EXISTS `lkt_auction_collection`;
CREATE TABLE `lkt_auction_collection` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `session_id` int(11) DEFAULT NULL COMMENT '场次id',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='竞拍收藏表';

-- ----------------------------
-- Records of lkt_auction_collection
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_auction_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_auction_config`;
CREATE TABLE `lkt_auction_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `low_pepole` int(11) unsigned DEFAULT NULL COMMENT '最低开拍人数',
  `wait_time` int(11) unsigned DEFAULT NULL COMMENT '出价等待时间',
  `days` int(11) unsigned DEFAULT '7' COMMENT '保留天数',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `store_id` int(11) DEFAULT NULL COMMENT '商城id',
  `is_open` tinyint(2) DEFAULT '1' COMMENT '是否开启插件 0-不开启 1-开启',
  `order_failure` bigint(20) NOT NULL DEFAULT '1' COMMENT '订单失效 (单位 秒)',
  `auto_the_goods` bigint(20) NOT NULL DEFAULT '0' COMMENT '自动收货时间',
  `deliver_remind` bigint(20) NOT NULL DEFAULT '0' COMMENT '发货提醒设置',
  `agree_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `agree_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='竞拍规则表';

-- ----------------------------
-- Records of lkt_auction_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_auction_product
-- ----------------------------
DROP TABLE IF EXISTS `lkt_auction_product`;
CREATE TABLE `lkt_auction_product` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `session_id` int(11) DEFAULT '0' COMMENT '场次id',
  `goods_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `attr_id` int(11) DEFAULT '0' COMMENT '商品规格id',
  `starting_amt` decimal(12,2) DEFAULT NULL COMMENT '起拍价',
  `mark_up_amt` decimal(12,2) DEFAULT NULL COMMENT '加价幅度',
  `goods_price` decimal(12,2) DEFAULT NULL COMMENT '商品价格',
  `price` decimal(12,2) DEFAULT NULL COMMENT '当前出价',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` int(11) DEFAULT '0' COMMENT '0=待拍卖 1=拍卖中 2=已拍卖 3=已流拍',
  `sNo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_show` int(11) DEFAULT '0' COMMENT '是否显示',
  `recovery` int(11) DEFAULT '0' COMMENT '回收标识',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `update_date` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=531 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='竞拍商品表';

-- ----------------------------
-- Records of lkt_auction_product
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_auction_promise
-- ----------------------------
DROP TABLE IF EXISTS `lkt_auction_promise`;
CREATE TABLE `lkt_auction_promise` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `promise` decimal(12,2) DEFAULT NULL COMMENT '保证金额',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `special_id` int(11) DEFAULT '0' COMMENT '专场id',
  `trade_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_pay` int(2) DEFAULT NULL COMMENT '是否成功支付 0失败,1成功',
  `is_back` int(2) DEFAULT NULL COMMENT '是否退款成功  1-成功 2-失败',
  `is_deduction` int(2) DEFAULT '0' COMMENT '是否扣除 0=未扣除,1=已扣除',
  `allow_back` tinyint(2) DEFAULT '1' COMMENT '是否符合退款标准  0：不符合 1：符合',
  `recovery` int(11) DEFAULT '0' COMMENT '回收标识',
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address_id` int(11) NOT NULL DEFAULT '0' COMMENT '收货地址id',
  `source` int(11) NOT NULL DEFAULT '0' COMMENT '来源 1.小程序 2.app 3.支付宝小程序 4.头条小程序 5.百度小程序 6.pc端 7.H5',
  `back_time` timestamp NULL DEFAULT NULL COMMENT '退款时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='竞拍保证金表';

-- ----------------------------
-- Records of lkt_auction_promise
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_auction_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_auction_record`;
CREATE TABLE `lkt_auction_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `auction_id` int(11) NOT NULL COMMENT '竞拍商品id',
  `add_time` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  `price` decimal(12,2) DEFAULT NULL COMMENT '竞拍价格',
  `user_id` char(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='竞拍记录表';

-- ----------------------------
-- Records of lkt_auction_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_auction_remind
-- ----------------------------
DROP TABLE IF EXISTS `lkt_auction_remind`;
CREATE TABLE `lkt_auction_remind` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `special_id` int(11) DEFAULT NULL COMMENT '专场id',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_remind` int(11) NOT NULL DEFAULT '0' COMMENT '是否提醒过',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='竞拍专场提醒表';

-- ----------------------------
-- Records of lkt_auction_remind
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_auction_session
-- ----------------------------
DROP TABLE IF EXISTS `lkt_auction_session`;
CREATE TABLE `lkt_auction_session` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `special_id` int(11) DEFAULT '0' COMMENT '专场id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `start_date` datetime NOT NULL COMMENT '开始时间',
  `end_date` datetime NOT NULL COMMENT '结束时间',
  `status` int(11) DEFAULT '1' COMMENT '1=未开始 2=进行中 3=已结束',
  `is_show` int(11) DEFAULT '1' COMMENT '是否显示',
  `recovery` int(11) DEFAULT '0' COMMENT '回收标识',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `update_date` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='竞拍场次表';

-- ----------------------------
-- Records of lkt_auction_session
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_auction_special
-- ----------------------------
DROP TABLE IF EXISTS `lkt_auction_special`;
CREATE TABLE `lkt_auction_special` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `commission` decimal(10,2) DEFAULT NULL COMMENT '佣金',
  `promise_amt` decimal(12,2) DEFAULT NULL COMMENT '保证金金额',
  `look_count` int(11) DEFAULT '0' COMMENT '围观人数',
  `start_date` datetime NOT NULL COMMENT '开始时间',
  `end_date` datetime NOT NULL COMMENT '结束时间',
  `sign_end_date` datetime DEFAULT NULL COMMENT '报名截至时间',
  `is_show` int(11) NOT NULL DEFAULT '1' COMMENT '是否显示',
  `status` int(11) DEFAULT '1' COMMENT '1=未开始 2=进行中 3=已结束',
  `type` int(11) DEFAULT '1' COMMENT '专场类型 1=店铺专场 2=普通专场 3=报名专场',
  `unit` int(11) DEFAULT '1' COMMENT '起拍价默认单位 1=固定金额 2=价格百分比',
  `number` decimal(12,2) NOT NULL COMMENT '起拍价默认值',
  `mark_up_amt` decimal(12,2) NOT NULL COMMENT '默认加价金额',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_settlement` int(11) DEFAULT '0' COMMENT '是否结算 0=否 1=是',
  `recovery` int(11) DEFAULT '0' COMMENT '回收标识',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `update_date` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='专场表';

-- ----------------------------
-- Records of lkt_auction_special
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_authority_mapping
-- ----------------------------
DROP TABLE IF EXISTS `lkt_authority_mapping`;
CREATE TABLE `lkt_authority_mapping` (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `role_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `menu_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='通用菜单权限表';

-- ----------------------------
-- Records of lkt_authority_mapping
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_backup_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_backup_config`;
CREATE TABLE `lkt_backup_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '配置id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `is_open` int(11) NOT NULL DEFAULT '0' COMMENT '是否开启自动备份,0关闭，1开启',
  `execute_cycle` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `query_data` int(11) DEFAULT NULL COMMENT '前端回显需要',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='数据备份配置表';

-- ----------------------------
-- Records of lkt_backup_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_bank_card
-- ----------------------------
DROP TABLE IF EXISTS `lkt_bank_card`;
CREATE TABLE `lkt_bank_card` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `store_id` int(11) NOT NULL COMMENT '商城ID',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mch_id` int(11) DEFAULT NULL COMMENT '店铺id',
  `Cardholder` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Bank_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `branch` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Bank_card_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认 1默认',
  `recycle` tinyint(1) NOT NULL DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='提现银行卡信息';

-- ----------------------------
-- Records of lkt_bank_card
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_banner
-- ----------------------------
DROP TABLE IF EXISTS `lkt_banner`;
CREATE TABLE `lkt_banner` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `image` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `open_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `url` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `type` tinyint(4) DEFAULT '1' COMMENT '类型 1.分类 2.商品 3.店铺 4.pc店铺 0=自定义',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='轮播图表';

-- ----------------------------
