-- Table structure for lkt_bbs_category
-- ----------------------------
DROP TABLE IF EXISTS `lkt_bbs_category`;
CREATE TABLE `lkt_bbs_category` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `sid` bigint(20) NOT NULL DEFAULT '0' COMMENT '上级ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '选中分类图片',
  `bimg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '未选中分类图片',
  `level` int(11) NOT NULL DEFAULT '0' COMMENT '等级',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序',
  `recycle` tinyint(4) DEFAULT '0' COMMENT '是否删除 0.未删除 1.删除',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `is_popular` tinyint(4) DEFAULT '0' COMMENT '是否是热门 0.不是热门 1.热门',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

