-- ----------------------------
-- Table structure for lkt_bbs_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_bbs_config`;
CREATE TABLE `lkt_bbs_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `is_status` tinyint(4) DEFAULT '0' COMMENT '开关 0.关闭 1.开启',
  `definition_template_id` int(11) DEFAULT NULL COMMENT '视频转码模板id',
  `sample_template_id` int(11) DEFAULT NULL COMMENT '视频采样截图模板id',
  `license_url` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '播放器许可证url',
  `secret_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '密钥',
  `security_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '防盗链 key',
  `region` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '储存位置',
  `secret_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '密钥id',
  `appid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'appid',
  `expire_time` int(11) DEFAULT NULL COMMENT '过期时间(单位：小时)',
  `notify_url` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '回调地址',
  `is_cdn` tinyint(4) DEFAULT '0' COMMENT '是否开启cdn 0：关闭 1：开启',
  `cdn_url` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'cdn域名播放地址',
  `notice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '须知',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

