-- Table structure for lkt_bbs_forum
-- ----------------------------
DROP TABLE IF EXISTS `lkt_bbs_forum`;
CREATE TABLE `lkt_bbs_forum` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '圈子名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '简介',
  `cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '封面',
  `head_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '圈子头像',
  `category_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '圈子分类',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'user_id',
  `need_platform_review` tinyint(4) DEFAULT '0' COMMENT '是否需要种草官审核 0.不需要 1.需要',
  `status` tinyint(4) DEFAULT '1' COMMENT '状态 1.待审核  2.审核通过 3.审核未通过',
  `refuse_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '拒绝理由',
  `like_num` int(11) NOT NULL DEFAULT '0' COMMENT '点赞数',
  `post_num` int(11) NOT NULL DEFAULT '0' COMMENT '发布文章数',
  `collect_num` int(11) NOT NULL DEFAULT '0' COMMENT '收藏数',
  `forward_num` int(11) NOT NULL DEFAULT '0' COMMENT '转发数',
  `follow_num` int(11) NOT NULL DEFAULT '0' COMMENT '关注数',
  `recycle` tinyint(4) DEFAULT '0' COMMENT '是否删除 0.未删除 1.删除',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='种草官表';

