-- Table structure for lkt_bbs_label
-- ----------------------------
DROP TABLE IF EXISTS `lkt_bbs_label`;
CREATE TABLE `lkt_bbs_label` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户id',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标签名',
  `recycle` tinyint(1) DEFAULT '0' COMMENT '是否删除 0.未删除 1.删除',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='标签表';

