  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `label_id` bigint(20) NOT NULL COMMENT '标签id',
  `post_id` bigint(20) NOT NULL COMMENT '文章id',
  PRIMARY KEY (`id`) USING BTREE
