  `store_id` int(11) NOT NULL COMMENT '商城id',
  `money` decimal(12,2) NOT NULL COMMENT '保证金金额',
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `trade_no` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_pay` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否支付（1是 0否）',
  `is_back` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否退款（1是 0否）',
