-- Table structure for lkt_buy_again
-- ----------------------------
DROP TABLE IF EXISTS `lkt_buy_again`;
CREATE TABLE `lkt_buy_again` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `store_id` int(11) NOT NULL COMMENT '商户ID',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Goods_id` int(11) NOT NULL COMMENT '产品ID',
  `Goods_num` int(11) NOT NULL COMMENT '数量',
  `Create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  `Size_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pro_type` tinyint(2) DEFAULT '0' COMMENT '商品类型 0.实物商品 1.虚拟商品',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=124 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='再次购买商品数据表';

-- ----------------------------
-- Records of lkt_buy_again
