-- Table structure for lkt_cart
-- ----------------------------
DROP TABLE IF EXISTS `lkt_cart`;
CREATE TABLE `lkt_cart` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Uid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Goods_id` int(11) DEFAULT NULL COMMENT '产品id',
  `Goods_num` int(11) DEFAULT NULL COMMENT '数量',
  `Create_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `Size_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pro_type` tinyint(2) DEFAULT '0' COMMENT '商品类型 0.实物商品 1.虚拟商品',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=347 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='购物车';

-- ----------------------------
-- Records of lkt_cart
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_cashier_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_cashier_record`;
CREATE TABLE `lkt_cashier_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `money` decimal(12,2) NOT NULL COMMENT '收款金额',
  `sourceNickname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `out_trade_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `transaction_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '状态 1.成功 2.失败',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '二维码生成时间',
  `success_time` timestamp NULL DEFAULT NULL COMMENT '支付完成时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='收银台记录表';

-- ----------------------------
-- Records of lkt_cashier_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_client
-- ----------------------------
DROP TABLE IF EXISTS `lkt_client`;
CREATE TABLE `lkt_client` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `permission` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `admin_id` int(11) NOT NULL DEFAULT '0' COMMENT '管理员id',
  `add_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='客户端表';

-- ----------------------------
-- Records of lkt_client
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_comments
-- ----------------------------
DROP TABLE IF EXISTS `lkt_comments`;
CREATE TABLE `lkt_comments` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `oid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `uid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `attribute_id` int(11) DEFAULT NULL COMMENT '属性id',
  `size` char(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `CommentType` char(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `anonymous` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` datetime DEFAULT NULL COMMENT '添加时间',
  `review` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `review_time` datetime DEFAULT NULL COMMENT '追评时间',
  `type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `order_detail_id` int(100) NOT NULL DEFAULT '0' COMMENT '订单详情id',
  `is_look` int(11) NOT NULL DEFAULT '0' COMMENT '商家是否以查看评论 0未查看 1已查看',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `attribute_id` (`attribute_id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `oid` (`oid`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE,
  KEY `pid` (`pid`) USING BTREE,
  KEY `attribute_id_2` (`attribute_id`) USING BTREE,
  KEY `order_detail_id` (`order_detail_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=656 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='评论表';

-- ----------------------------
-- Records of lkt_comments
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_comments_img
-- ----------------------------
DROP TABLE IF EXISTS `lkt_comments_img`;
CREATE TABLE `lkt_comments_img` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '图片id',
  `comments_url` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `comments_id` int(11) DEFAULT NULL COMMENT '评论id',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `type` tinyint(3) DEFAULT '0' COMMENT '类型 0:评论  1:追评',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='评论图片表';

-- ----------------------------
-- Records of lkt_comments_img
