-- ----------------------------
-- Table structure for lkt_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_config`;
CREATE TABLE `lkt_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `is_register` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否需要注册 1.注册 2.免注册',
  `logo` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `logo1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `company` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '公司名称',
  `appid` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `appsecret` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `domain` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商城根目录域名',
  `app_domain_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `H5_domain` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'H5地址',
  `mch_id` int(11) DEFAULT NULL COMMENT '商户id',
  `ip` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `uploadImg_domain` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `upserver` tinyint(4) NOT NULL DEFAULT '2' COMMENT '上传服务器:1,本地　2,阿里云 3,腾讯云 4,七牛云',
  `uploadImg` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `upload_file` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `modify_date` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `mch_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mch_cert` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `wx_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '默认微信名称',
  `wx_headimgurl` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '默认微信头像',
  `customer_service` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '客服',
  `agreement` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `aboutus` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `message_day` int(10) NOT NULL DEFAULT '0' COMMENT '消息保留天数',
  `tencent_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `after_sales_issues` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '售后问题',
  `payment_issues` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `shopping_process` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `payment_method` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `return_policy` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '退货政策',
  `cancellation_order` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `refund_process` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '退款流程',
  `refund_instructions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '退款说明',
  `exp_time` int(11) DEFAULT '2' COMMENT '移动端登录有效期',
  `is_push` tinyint(4) DEFAULT '0' COMMENT '是否推送 0.不推送 1.推送',
  `push_Appkey` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `push_Appid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `push_MasterECRET` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_express` tinyint(4) DEFAULT '0' COMMENT '是否开启快递100  0.不开启 1.开\r\n\r\n启',
  `express_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `express_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `express_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `express_tel` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `express_secret` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `express_tempId` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_Kicking` tinyint(4) DEFAULT '0' COMMENT '是否登录踢人  0.不开启 1.开启',
  `Hide_your_wallet` tinyint(4) DEFAULT '0' COMMENT '是否隐藏钱包 0.不隐藏 1.隐藏',
  `watermark_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `watermark_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `pc_mch_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'PC店铺地址',
  `app_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `app_logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_accounts` int(11) DEFAULT NULL COMMENT '是否分账',
  `accounts_set` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分账账号',
  `logon_logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '登录logo',
  `copyright_information` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '版权信息',
  `record_information` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备案信息',
  `link_to_landing_page` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '登录页友情链接',
  `admin_default_portrait` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '默认头像设置',
  `android_download_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '安卓下载地址',
  `ios_download_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'IOS下载地址',
  `default_lang_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'zh_CN' COMMENT '商城默认语种',
  `default_currency` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商城默认币种',
  `mail_config` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '邮箱配置',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=480 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='系统配置表';

-- ----------------------------
-- Records of lkt_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_configure
-- ----------------------------
DROP TABLE IF EXISTS `lkt_configure`;
CREATE TABLE `lkt_configure` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '配置id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `color` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `size` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `costprice` decimal(12,2) NOT NULL COMMENT '成本价',
  `price` decimal(12,2) NOT NULL COMMENT '出售价格',
  `yprice` decimal(12,2) NOT NULL COMMENT '原价格',
  `msrp` decimal(12,2) NOT NULL COMMENT '建议零售价',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pid` int(11) NOT NULL COMMENT '商品id',
  `total_num` int(11) NOT NULL DEFAULT '0' COMMENT '总库存',
  `num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '剩余库存',
  `unit` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bar_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bargain_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '砍价开始价格',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '状态 0:未开启砍价 1:开启砍价 2 上架 3 缺货 4下架',
  `attribute` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  `min_inventory` int(11) NOT NULL DEFAULT '10' COMMENT '产品预警值',
  `ctime` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `attribute_str` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `supplier_superior` int(11) DEFAULT NULL COMMENT '供应商商品规格上级id',
  `write_off_num` int(11) DEFAULT '0' COMMENT '虚拟商品可核销次数(暂时未使用，使用的总库存)',
  `commission` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `update_time` timestamp NULL DEFAULT NULL COMMENT '修改佣金比例的时间',
  `live_price` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '直播价格',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id` (`id`) USING BTREE,
  KEY `pid` (`pid`) USING BTREE,
  KEY `recycle` (`recycle`) USING BTREE,
  KEY `name` (`name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1464 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品规格配置表';

-- ----------------------------
-- Records of lkt_configure
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_core_menu
-- ----------------------------
DROP TABLE IF EXISTS `lkt_core_menu`;
CREATE TABLE `lkt_core_menu` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `s_id` int(11) DEFAULT NULL COMMENT '上级id',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `image1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `module` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `action` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `url` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sort` int(11) DEFAULT '0' COMMENT '菜单排序',
  `level` int(11) DEFAULT NULL COMMENT '第几级',
  `is_core` tinyint(4) DEFAULT '0' COMMENT '是否是核心',
  `is_plug_in` tinyint(4) DEFAULT '0' COMMENT '是否是插件',
  `type` tinyint(4) DEFAULT '0' COMMENT '类型 0=控制台 1=商城',
  `add_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  `is_display` tinyint(4) DEFAULT '0' COMMENT '是否显示 0.不显示 1.显示',
  `briefintroduction` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `guide_sort` int(11) DEFAULT '0' COMMENT '导览排序',
  `guide_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_button` int(4) DEFAULT '0' COMMENT '是否为按钮',
  `is_tab` int(4) DEFAULT '0' COMMENT '是否为tab页面    0不是  1是',
  `lang_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'zh_CN' COMMENT '语言',
  `country_num` int(11) DEFAULT '156' COMMENT '国家语种默认156',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id` (`id`) USING BTREE,
  KEY `s_id` (`s_id`) USING BTREE,
  KEY `sort` (`sort`) USING BTREE,
  KEY `recycle` (`recycle`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7621 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='核心菜单';

-- ----------------------------
-- Records of lkt_core_menu
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_coupon
-- ----------------------------
DROP TABLE IF EXISTS `lkt_coupon`;
CREATE TABLE `lkt_coupon` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  `user_id` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `money` int(11) NOT NULL DEFAULT '0' COMMENT '优惠券金额',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '领取时间',
  `expiry_time` timestamp NULL DEFAULT NULL COMMENT '到期时间',
  `hid` int(11) NOT NULL DEFAULT '0' COMMENT '活动id',
  `type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '类型 0:未使用 1:使用中 2:已使\r\n\r\n用 3:已过期',
  `status` tinyint(4) DEFAULT '0' COMMENT '状态 0.开启 1.禁用',
  `free_or_not` tinyint(3) DEFAULT '0' COMMENT '是否为赠送 0.不为赠送 1.赠送',
  `recycle` tinyint(4) DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=294 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='优惠券表';

-- ----------------------------
-- Records of lkt_coupon
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_coupon_activity
-- ----------------------------
DROP TABLE IF EXISTS `lkt_coupon_activity`;
CREATE TABLE `lkt_coupon_activity` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺id',
  `name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `activity_type` int(11) DEFAULT '0' COMMENT '优惠券类型 1=免邮 2=满减 3=折扣 4=会员赠送',
  `grade_id` int(11) DEFAULT NULL COMMENT '会员等级ID',
  `money` decimal(12,2) DEFAULT NULL COMMENT '优惠券面值',
  `discount` decimal(12,2) DEFAULT NULL COMMENT '折扣值',
  `consumption_threshold_type` tinyint(4) DEFAULT '1' COMMENT '消费门口  1.无门槛  2.有门槛',
  `z_money` decimal(12,2) DEFAULT NULL COMMENT '消费满多少',
  `shopping` int(11) NOT NULL DEFAULT '0' COMMENT '满多少赠券',
  `free_mail_task` tinyint(4) NOT NULL DEFAULT '0' COMMENT '免邮任务 0：完善资料 1：绑定手机',
  `circulation` int(11) DEFAULT '0' COMMENT '发行数量',
  `num` int(11) DEFAULT NULL COMMENT '剩余数量',
  `receive` int(11) DEFAULT NULL COMMENT '领取限制',
  `use_num` int(11) DEFAULT NULL COMMENT '使用限制',
  `start_time` timestamp NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` timestamp NULL DEFAULT NULL COMMENT '结束时间',
  `type` tinyint(4) DEFAULT '1' COMMENT '优惠券使用范围 1：全部商品 2:指定商品 3：指定分类\r\n4：充值会员',
  `product_class_id` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `product_id` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `skip_type` tinyint(4) DEFAULT '1' COMMENT '跳转方式 1.首页 2.\r\n\r\n自定义',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(4) DEFAULT '0' COMMENT '状态 0：未启用 1：启用 2:禁用 3：已结束',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `qualifications` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `recycle` tinyint(4) DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  `day` int(11) DEFAULT NULL COMMENT '有效时间',
  `Instructions` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_display` tinyint(4) DEFAULT '1' COMMENT '是否显示 0.不显示 1.显示',
  `issue_unit` int(11) DEFAULT '1' COMMENT '发行单位 0=商城 1=店铺',
  `receive_type` int(11) DEFAULT '0' COMMENT '领取方式 0=手动领取 1=系统赠送',
  `is_auto_push` int(11) DEFAULT '0' COMMENT '是否已自动发放',
  `cover_map` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '优惠券图片',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='优惠劵活动表';

-- ----------------------------
-- Records of lkt_coupon_activity
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_coupon_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_coupon_config`;
CREATE TABLE `lkt_coupon_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺id',
  `is_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '开关 0.关闭 1.开启',
  `coupon_del` tinyint(4) DEFAULT NULL COMMENT '优惠券删除',
  `coupon_day` int(11) DEFAULT NULL COMMENT '优惠券删除天数',
  `activity_del` tinyint(4) DEFAULT NULL COMMENT '优惠券活动删除',
  `activity_day` int(11) DEFAULT NULL COMMENT '优惠券活动删除天数',
  `payment_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '支付设置 0：只使用优惠券 1：可与其他优惠一起使用',
  `limit_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '限领设置 0：单张 1：多张',
  `coupon_type` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `modify_date` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `is_show` tinyint(4) DEFAULT '0' COMMENT '店铺优惠券设置 0：未启用 1：启用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='优惠券设置表';

-- ----------------------------
-- Records of lkt_coupon_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_coupon_presentation_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_coupon_presentation_record`;
CREATE TABLE `lkt_coupon_presentation_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `coupon_activity_id` int(11) NOT NULL DEFAULT '0' COMMENT '优惠券活动id',
  `coupon_id` int(11) NOT NULL DEFAULT '0' COMMENT '优惠券id',
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `activity_type` int(11) NOT NULL DEFAULT '0' COMMENT '优惠券类型',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=152 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='赠送优惠券记录表';

-- ----------------------------
-- Records of lkt_coupon_presentation_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_coupon_sno
-- ----------------------------
DROP TABLE IF EXISTS `lkt_coupon_sno`;
CREATE TABLE `lkt_coupon_sno` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `coupon_id` int(11) NOT NULL DEFAULT '0' COMMENT '优惠券id',
  `sNo` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0:正常 1:回收',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=232 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='优惠券关联表';

-- ----------------------------
-- Records of lkt_coupon_sno
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_currency
-- ----------------------------
DROP TABLE IF EXISTS `lkt_currency`;
CREATE TABLE `lkt_currency` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `currency_code` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ISO货币代码(如USD)',
  `currency_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '货币名称',
  `is_show` int(11) NOT NULL DEFAULT '1' COMMENT '是否展示 0 不展示 1展示 ',
  `currency_symbol` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '货币符号($)',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '是否删除 0 未删除 1已删除 ',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='平台货币信息';

-- ----------------------------
-- Records of lkt_currency
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_currency_store
-- ----------------------------
DROP TABLE IF EXISTS `lkt_currency_store`;
CREATE TABLE `lkt_currency_store` (
  `store_id` int(11) DEFAULT NULL COMMENT '商城id',
  `currency_id` int(11) DEFAULT NULL COMMENT '货币id',
  `is_show` int(11) NOT NULL DEFAULT '1' COMMENT '是否展示 0 不展示 1展示 ',
  `default_currency` int(11) DEFAULT '0' COMMENT '是否商城基础货币【结算货币】默认 0 否 1 是',
  `exchange_rate` decimal(10,4) NOT NULL COMMENT '基础货币汇率',
  `recycle` int(11) NOT NULL DEFAULT '1' COMMENT '是否删除 0 未删除 1已删除 ',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商城货币';

-- ----------------------------
-- Records of lkt_currency_store
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_customer
-- ----------------------------
DROP TABLE IF EXISTS `lkt_customer`;
CREATE TABLE `lkt_customer` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `admin_id` int(11) NOT NULL DEFAULT '0' COMMENT '管理员id',
  `customer_number` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户编号',
  `name` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '姓名',
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '手机',
  `price` decimal(12,2) NOT NULL COMMENT '价格',
  `company` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '公司名称',
  `function` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_date` timestamp NULL DEFAULT NULL COMMENT '购买时间',
  `end_date` datetime DEFAULT NULL COMMENT '到期时间',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '类型 0:启用 1:到期 2:锁定',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0:不回收 1:回收 ',
  `is_default` tinyint(4) DEFAULT '0' COMMENT '是否默认 0.不是默认 1.默认',
  `contact_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系地址',
  `contact_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系电话',
  `copyright_information` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '版权信息',
  `record_information` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备案信息',
  `official_website` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '官方网址',
  `merchant_logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商户logo',
  `store_langs` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '商城语种',
  `cpc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '86' COMMENT '区号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=124 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商城表';

-- ----------------------------
-- Records of lkt_customer
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_data_dictionary_list
-- ----------------------------
DROP TABLE IF EXISTS `lkt_data_dictionary_list`;
CREATE TABLE `lkt_data_dictionary_list` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sid` int(11) NOT NULL DEFAULT '0' COMMENT '数据字典名称ID',
  `s_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `value` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否生效 0:不是 1:是',
  `admin_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0:正常 1:回收',
  `add_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `lang_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'zh_CN' COMMENT '语种',
  `country_num` int(11) DEFAULT '156' COMMENT '所属国家',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=505 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='数据字典目录表';

-- ----------------------------
-- Records of lkt_data_dictionary_list
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_data_dictionary_name
-- ----------------------------
DROP TABLE IF EXISTS `lkt_data_dictionary_name`;
CREATE TABLE `lkt_data_dictionary_name` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否生效 0:不是 1:是',
  `admin_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dic_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_core` int(11) NOT NULL DEFAULT '0' COMMENT '是否是系统核心字典',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0:正常 1:回收',
  `add_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `lang_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'zh_CN' COMMENT '语种编码',
  `country_num` int(11) DEFAULT '156' COMMENT '国家编码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='数据字典名称表';

-- ----------------------------
-- Records of lkt_data_dictionary_name
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_distribution_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_distribution_config`;
CREATE TABLE `lkt_distribution_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `sets` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `status` int(5) NOT NULL DEFAULT '0' COMMENT '插件状态 0关闭 1开启',
  `advertising` tinyint(1) NOT NULL DEFAULT '0' COMMENT '加盟广告（0不开启1开启）',
  `ad_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `relationship` tinyint(1) NOT NULL DEFAULT '0' COMMENT '关系确定方式0注册确定1消费确定',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `store_id_idx` (`store_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='分销设置表';

-- ----------------------------
-- Records of lkt_distribution_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_distribution_goods
-- ----------------------------
DROP TABLE IF EXISTS `lkt_distribution_goods`;
CREATE TABLE `lkt_distribution_goods` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `store_id` int(11) NOT NULL COMMENT '商城ID',
  `p_id` int(11) NOT NULL COMMENT '商品ID',
  `s_id` int(11) NOT NULL COMMENT '属性ID',
  `pv` decimal(12,2) NOT NULL COMMENT 'pv值',
  `uplevel` int(11) DEFAULT '0' COMMENT '晋升等级\r\n一次性消费满足金额 onebuy \r\n推荐recomm[0]个级别为recomm[1]会员\r\n累计消费满manybuy\r\n累计业绩满manyyeji[0]\r\n直推人数满manypeople[0]个，团队人数满manypeople[1]个',
  `distribution_rule` tinyint(1) NOT NULL DEFAULT '1' COMMENT '分销规则类型 1等级规则 2自定义',
  `rules_set` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '自定义规则设置',
  `add_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  `recycle` tinyint(1) NOT NULL DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='分销商品表';

-- ----------------------------
-- Records of lkt_distribution_goods
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_distribution_grade
-- ----------------------------
DROP TABLE IF EXISTS `lkt_distribution_grade`;
CREATE TABLE `lkt_distribution_grade` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `sets` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `datetime` datetime NOT NULL COMMENT '创建时间',
  `is_agent` int(2) DEFAULT '0' COMMENT '是否为代理商',
  `is_ordinary` int(2) DEFAULT '0' COMMENT '是否是普通分销商0 不是 1是',
  `transfer_balance` int(5) DEFAULT '0' COMMENT '推荐后消费金转余额比例',
  `sort` int(4) DEFAULT '1' COMMENT '排序号',
  `discount` decimal(12,2) DEFAULT NULL COMMENT '购物折扣',
  `integral` int(12) DEFAULT '0' COMMENT '积分',
  `member_proportion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `member_consumer_money` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `uplevel_obj` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='分销商等级表';

-- ----------------------------
-- Records of lkt_distribution_grade
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_distribution_log
-- ----------------------------
DROP TABLE IF EXISTS `lkt_distribution_log`;
CREATE TABLE `lkt_distribution_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `store_id` int(11) NOT NULL COMMENT '商户ID',
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `operator` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `old_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `new_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `event` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='分销用户信息修改日志';

-- ----------------------------
-- Records of lkt_distribution_log
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_distribution_ranking
-- ----------------------------
DROP TABLE IF EXISTS `lkt_distribution_ranking`;
CREATE TABLE `lkt_distribution_ranking` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `store_id` int(11) NOT NULL COMMENT '商城ID',
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `zhanghao` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `commission` decimal(12,2) NOT NULL COMMENT '佣金',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '排行类型 1今日2本周3本月4本年',
  `add_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='分佣排行表';

-- ----------------------------
-- Records of lkt_distribution_ranking
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_distribution_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_distribution_record`;
CREATE TABLE `lkt_distribution_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `from_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `money` decimal(12,2) NOT NULL COMMENT '佣金金额',
  `sNo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `level` int(5) DEFAULT NULL COMMENT '层级',
  `event` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '类型 1:转入(收入) 2:提现 3:个人进获奖8:充值积分9转出',
  `genre` tinyint(1) NOT NULL DEFAULT '1' COMMENT '分佣类型 1直推分佣2间推分佣3平级奖4级差奖',
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `status` int(10) NOT NULL DEFAULT '0' COMMENT '是否发放',
  `user_level` int(11) NOT NULL DEFAULT '0' COMMENT '用户当前分销等级',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='佣金日志表';

-- ----------------------------
-- Records of lkt_distribution_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_distribution_withdraw
-- ----------------------------
DROP TABLE IF EXISTS `lkt_distribution_withdraw`;
CREATE TABLE `lkt_distribution_withdraw` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `wx_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Bank_id` int(11) NOT NULL COMMENT '银行卡id',
  `money` decimal(12,2) NOT NULL COMMENT '提现金额',
  `z_money` decimal(12,2) NOT NULL COMMENT '剩余金额',
  `s_charge` decimal(12,2) NOT NULL COMMENT '手续费',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '状态 0：审核中 1：审核通过 2：拒绝',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '申请时间',
  `refuse` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_mch` int(2) DEFAULT '0' COMMENT '是否是店铺提现',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='提现列表';

-- ----------------------------
-- Records of lkt_distribution_withdraw
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_diy
-- ----------------------------
DROP TABLE IF EXISTS `lkt_diy`;
CREATE TABLE `lkt_diy` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '版本号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '页面名称',
  `value` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '页面数据',
  `tabber_info` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '导航配置信息',
  `tab_bar` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '导航',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `theme_dict_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '主题类型code（字典code）',
  `theme_type` tinyint(1) DEFAULT '1' COMMENT '主题类型 1:系统主题 2:自定义主题',
  `add_time` int(11) DEFAULT NULL COMMENT '添加时间',
  `update_time` int(11) DEFAULT NULL COMMENT '更新时间',
  `status` tinyint(1) DEFAULT '0' COMMENT '是否使用',
  `type` tinyint(1) DEFAULT NULL COMMENT '页面类型',
  `is_del` tinyint(1) DEFAULT '0' COMMENT '是否删除',
  `store_id` int(11) NOT NULL COMMENT '商城ID',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  `cover` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '封面图',
  `lang_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'zh_CN' COMMENT '语言',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `store_ID_idx` (`store_id`) USING BTREE,
  KEY `status_idx` (`status`) USING BTREE,
  KEY `is_del_idx` (`is_del`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='DIY数据表';

-- ----------------------------
-- Records of lkt_diy
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_diy_page
-- ----------------------------
DROP TABLE IF EXISTS `lkt_diy_page`;
CREATE TABLE `lkt_diy_page` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '页面id',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `page_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL COMMENT '页面名称',
  `type` tinyint(1) DEFAULT NULL COMMENT '类型 1：系统页面 2：自定义页面',
  `link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '链接',
  `page_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '页面对应的key',
  `image` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `page_context` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '页面内容',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态 0:不启用 1:启用',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '是否回收 0：显示 1：回收',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='diy页面';

-- ----------------------------
-- Records of lkt_diy_page
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_diy_page_bind
-- ----------------------------
DROP TABLE IF EXISTS `lkt_diy_page_bind`;
CREATE TABLE `lkt_diy_page_bind` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `diy_id` int(11) NOT NULL COMMENT 'diy主键',
  `diy_page_id` int(11) NOT NULL COMMENT '自定义页面id',
  `link_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'diy数据使用链接对应的json key',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '子组件value',
  `bind_time` datetime DEFAULT NULL COMMENT '绑定时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=192 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='diy页面绑定关系';

-- ----------------------------
-- Records of lkt_diy_page_bind
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_drafts
-- ----------------------------
DROP TABLE IF EXISTS `lkt_drafts`;
CREATE TABLE `lkt_drafts` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) DEFAULT '0' COMMENT '商城ID',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  `supplier_id` int(11) DEFAULT '0' COMMENT '供应商ID',
  `text` text CHARACTER SET utf8 COLLATE utf8_general_ci COMMENT '草根数据',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=109 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='草稿箱';

-- ----------------------------
-- Records of lkt_drafts
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_ds_country
-- ----------------------------
DROP TABLE IF EXISTS `lkt_ds_country`;
CREATE TABLE `lkt_ds_country` (
  `id` smallint(4) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '英文名称',
  `zh_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '中文名称',
  `code` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '编码',
  `num3` int(11) DEFAULT NULL COMMENT 'ITU电话代码\r\n',
  `code2` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '数字编码',
  `is_show` tinyint(2) NOT NULL DEFAULT '1' COMMENT '是否显示 1 显示 0 不显示',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `name` (`name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=244 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='国家信息';

-- ----------------------------
-- Records of lkt_ds_country
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_edition
-- ----------------------------
DROP TABLE IF EXISTS `lkt_edition`;
CREATE TABLE `lkt_edition` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `edition` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `edition_url` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否是热更新 0:是 1:不是',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `appname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `android_url` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ios_url` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='版本表';

-- ----------------------------
-- Records of lkt_edition
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_express
-- ----------------------------
DROP TABLE IF EXISTS `lkt_express`;
CREATE TABLE `lkt_express` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `kuaidi_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_open` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否开启1开启2关闭',
  `sort` int(11) DEFAULT '1' COMMENT '排序',
  `recycle` tinyint(1) DEFAULT '0' COMMENT '是否回收0显示1不显示',
  `add_date` datetime NOT NULL COMMENT '添加时间',
  `wx_delivery_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id` (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=91 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='快递公司';

-- ----------------------------
-- Records of lkt_express
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_express_delivery
-- ----------------------------
DROP TABLE IF EXISTS `lkt_express_delivery`;
CREATE TABLE `lkt_express_delivery` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `sNo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `order_details_id` int(11) DEFAULT '0' COMMENT '订单详情ID',
  `express_id` int(11) DEFAULT '0' COMMENT '快递公司ID',
  `courier_num` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `num` int(11) DEFAULT '0' COMMENT '商品数量',
  `deliver_time` datetime DEFAULT NULL COMMENT '发货时间',
  `childNum` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `returnNum` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `label` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `kdComOrderNum` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_status` tinyint(4) DEFAULT '0' COMMENT '是否打印 0.未打印 1.已打印',
  `subtable_id` int(11) NOT NULL DEFAULT '0' COMMENT '快递公司子表ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=442 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='快递发货记录表';

-- ----------------------------
-- Records of lkt_express_delivery
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_express_subtable
-- ----------------------------
DROP TABLE IF EXISTS `lkt_express_subtable`;
CREATE TABLE `lkt_express_subtable` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) DEFAULT '0' COMMENT '商城ID',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  `express_id` int(11) DEFAULT '0' COMMENT '主表ID',
  `partnerId` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `partnerKey` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `partnerSecret` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `partnerName` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `net` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `code` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `checkMan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_time` datetime DEFAULT NULL COMMENT '添加时间',
  `recovery` tinyint(4) DEFAULT '0' COMMENT '是否删除 0.未删除 1.已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='快递电子面单配置表';

-- ----------------------------
-- Records of lkt_express_subtable
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_extension
-- ----------------------------
DROP TABLE IF EXISTS `lkt_extension`;
CREATE TABLE `lkt_extension` (
  `id` int(15) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` char(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `image` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sort` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `x` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `y` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `kuan` int(5) NOT NULL DEFAULT '150' COMMENT '二维码宽度',
  `type` int(2) NOT NULL COMMENT '海报类型 1.文章海报 2.红包海报 3.商品海报 4.分销海报 5.邀请海报 6.竞拍海报',
  `keyword` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `isdefault` int(2) DEFAULT '0' COMMENT '是否默认',
  `bg` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `color` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `waittext` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `data` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `store_type` tinyint(4) DEFAULT '1' COMMENT '来源 1.小程序 2.app',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='推广海报图片表';

-- ----------------------------
-- Records of lkt_extension
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_file_delivery
-- ----------------------------
DROP TABLE IF EXISTS `lkt_file_delivery`;
CREATE TABLE `lkt_file_delivery` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) DEFAULT '0' COMMENT '商城ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `upload_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '0' COMMENT '文件状态 1=发货成功 0=发货失败',
  `text` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_del` int(11) DEFAULT '0' COMMENT '是否删除标识',
  `mch_id` int(11) DEFAULT NULL COMMENT '操作店铺id',
  `add_date` datetime DEFAULT NULL COMMENT '发货时间',
  `update_date` datetime DEFAULT NULL,
  `order_num` int(11) DEFAULT '0' COMMENT '发货订单数量/导入商品数',
  `type` int(11) DEFAULT '0' COMMENT '0导入上传商品  1批量发货',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='批量发货表';

-- ----------------------------
-- Records of lkt_file_delivery
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_files_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_files_record`;
CREATE TABLE `lkt_files_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `store_id` char(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `store_type` char(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `upload_mode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `image_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `recycle` tinyint(1) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.回收',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `explain` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `alternative_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `describe` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `supplier_id` int(10) DEFAULT NULL COMMENT '供应商id',
  `type` tinyint(4) DEFAULT '1' COMMENT '资源类型，1图片，2视频',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `recycle` (`recycle`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `mch_id` (`mch_id`) USING BTREE,
  KEY `image_name` (`image_name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=934 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='上传文件记录表';

-- ----------------------------
-- Records of lkt_files_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_finance_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_finance_config`;
CREATE TABLE `lkt_finance_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `plug_ins_id` int(11) NOT NULL DEFAULT '0' COMMENT '插件id',
  `min_cz` decimal(12,2) DEFAULT NULL COMMENT '最小充值金额',
  `min_amount` decimal(12,2) NOT NULL COMMENT '最少提现金额',
  `max_amount` decimal(12,2) NOT NULL COMMENT '最大提现金额',
  `service_charge` decimal(12,2) NOT NULL COMMENT '手续费',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `modify_date` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `multiple` int(6) DEFAULT '0' COMMENT '提现倍数',
  `transfer_multiple` int(6) DEFAULT '0' COMMENT '转账倍数',
  `cz_multiple` int(6) DEFAULT '100' COMMENT '充值倍数',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='钱包配置表';

-- ----------------------------
-- Records of lkt_finance_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_flashsale_activity
-- ----------------------------
DROP TABLE IF EXISTS `lkt_flashsale_activity`;
CREATE TABLE `lkt_flashsale_activity` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id自增',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `label_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `flashsale_price` decimal(11,2) NOT NULL COMMENT '折扣价格',
  `price_type` int(11) NOT NULL DEFAULT '0' COMMENT '价格单位 0=百分比 1=固定值',
  `discount` decimal(10,2) DEFAULT NULL COMMENT '折扣',
  `buylimit` int(11) DEFAULT NULL COMMENT '购买上限',
  `num` int(11) NOT NULL COMMENT '活动库存',
  `max_num` int(11) DEFAULT NULL COMMENT '最大数量',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` int(1) NOT NULL DEFAULT '1' COMMENT '活动状态 1 未开始 2 进行中 3结束',
  `type` tinyint(1) DEFAULT NULL COMMENT '活动类型',
  `starttime` datetime NOT NULL COMMENT '活动开始时间',
  `endtime` datetime NOT NULL COMMENT '活动结束时间',
  `isshow` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否显示 1 是 0 否',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除 1 是 0 否',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime DEFAULT NULL COMMENT '修改时间',
  `isNotice` int(11) NOT NULL DEFAULT '0' COMMENT '是否通知 0=未通知 1=已通知',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='限时折扣活动表';

-- ----------------------------
-- Records of lkt_flashsale_activity
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_flashsale_addgoods
-- ----------------------------
DROP TABLE IF EXISTS `lkt_flashsale_addgoods`;
CREATE TABLE `lkt_flashsale_addgoods` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0',
  `goods_id` int(11) NOT NULL COMMENT '商品ID',
  `attr_id` int(11) DEFAULT NULL COMMENT '属性id',
  `goods_price` decimal(11,2) NOT NULL COMMENT '商品价格',
  `price` decimal(11,2) NOT NULL COMMENT '加购价格',
  `num` int(11) NOT NULL DEFAULT '0' COMMENT '库存数量',
  `max_num` int(11) NOT NULL DEFAULT '0' COMMENT '上架库存',
  `sort` int(11) NOT NULL DEFAULT '1' COMMENT '排序',
  `is_delete` smallint(6) NOT NULL DEFAULT '0' COMMENT '是否删除:0否   1是',
  `add_time` datetime DEFAULT NULL COMMENT '添加时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '上架状态 1待上架， 2已上架 ， 3已下架',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=90 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='限时折扣加购商品表';

-- ----------------------------
-- Records of lkt_flashsale_addgoods
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_flashsale_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_flashsale_config`;
CREATE TABLE `lkt_flashsale_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键自增',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `is_open` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否开启 1 是 0 否',
  `order_after` int(11) NOT NULL DEFAULT '604800' COMMENT '订单售后时间 (单位秒)',
  `auto_the_goods` int(11) NOT NULL DEFAULT '7' COMMENT '自动收货时间',
  `auto_good_comment_day` int(5) NOT NULL DEFAULT '0' COMMENT '自动评价设置几后自动好评',
  `auto_good_comment_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `good_switch` tinyint(4) NOT NULL DEFAULT '0' COMMENT '自动评价设置 0.关闭 1.开启',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='限时折扣设置';

-- ----------------------------
-- Records of lkt_flashsale_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_flashsale_label
-- ----------------------------
DROP TABLE IF EXISTS `lkt_flashsale_label`;
CREATE TABLE `lkt_flashsale_label` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id自增',
  `store_id` int(11) DEFAULT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` int(1) DEFAULT '1' COMMENT '活动状态 1 未开始 2 进行中 3结束',
  `discount` decimal(10,2) DEFAULT NULL COMMENT '折扣',
  `buylimit` int(11) DEFAULT NULL COMMENT '购买上限',
  `is_show` int(11) NOT NULL DEFAULT '0',
  `starttime` datetime DEFAULT NULL COMMENT '活动开始时间',
  `endtime` datetime DEFAULT NULL COMMENT '活动结束时间',
  `sort` int(11) DEFAULT NULL COMMENT '序号',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `update_date` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `recovery` int(11) DEFAULT '0' COMMENT '是否回收',
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `update_source` int(11) NOT NULL DEFAULT '1' COMMENT '最后的更新来源 1为h5商家 2为pc店铺',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='限时折扣活动表';

-- ----------------------------
-- Records of lkt_flashsale_label
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_flashsale_pro
-- ----------------------------
DROP TABLE IF EXISTS `lkt_flashsale_pro`;
CREATE TABLE `lkt_flashsale_pro` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id自增',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `activity_id` int(50) NOT NULL COMMENT '插件活动id',
  `goods_id` int(11) DEFAULT NULL COMMENT '商品ID',
  `attr_id` int(11) DEFAULT '0' COMMENT '规格id',
  `num` int(11) NOT NULL COMMENT '活动库存',
  `max_num` int(11) DEFAULT NULL COMMENT '最大数量',
  `add_time` datetime NOT NULL COMMENT '添加日期',
  `is_delete` int(1) NOT NULL DEFAULT '0' COMMENT '是否删除 1 是 0 否',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='限时折扣商品表';

-- ----------------------------
-- Records of lkt_flashsale_pro
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_flashsale_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_flashsale_record`;
CREATE TABLE `lkt_flashsale_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id自增',
  `store_id` int(11) NOT NULL COMMENT '店铺id',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `activity_id` int(11) NOT NULL COMMENT '活动id',
  `time_id` int(11) NOT NULL COMMENT '时段id',
  `pro_id` int(11) NOT NULL COMMENT '商品id',
  `attr_id` int(11) NOT NULL COMMENT '规格id',
  `sec_id` int(11) NOT NULL COMMENT '限时折扣id',
  `price` decimal(11,2) NOT NULL COMMENT '价格',
  `num` int(11) NOT NULL COMMENT '数量',
  `sNo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除 1是 0否',
  `add_time` datetime NOT NULL COMMENT '添加日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=67 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='限时折扣记录表';

-- ----------------------------
-- Records of lkt_flashsale_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_freight
-- ----------------------------
DROP TABLE IF EXISTS `lkt_freight`;
CREATE TABLE `lkt_freight` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '类型 0:件 1:重量',
  `freight` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '指定运费',
  `is_default` tinyint(4) NOT NULL DEFAULT '0' COMMENT '类型 0:不默认 1:默认',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺id',
  `is_package_settings` int(11) DEFAULT '0' COMMENT '是否是包邮设置 0.未开启 1.开启',
  `package_settings` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_no_delivery` int(11) DEFAULT '0' COMMENT '是否不配送 0.未开启 1.开启',
  `no_delivery` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '不配送地区',
  `supplier_id` int(11) DEFAULT NULL COMMENT '供应商id',
  `default_freight` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '默认运费',
  `threeIdsList` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '不配送地区ID',
  `lang_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'zh_CN' COMMENT '语种编码',
  `country_num` int(11) NOT NULL DEFAULT '156' COMMENT '国家编码默认156中国',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `mch_id` (`mch_id`) USING BTREE,
  KEY `name` (`name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='运费表';

-- ----------------------------
-- Records of lkt_freight
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_go_group_order
-- ----------------------------
DROP TABLE IF EXISTS `lkt_go_group_order`;
CREATE TABLE `lkt_go_group_order` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `num` int(11) DEFAULT NULL COMMENT '数量',
  `z_price` decimal(12,2) DEFAULT NULL COMMENT '总价',
  `sNo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sheng` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `shi` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `xian` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `address` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `remark` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pay` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `pay_time` timestamp NULL DEFAULT NULL COMMENT '支付时间',
  `arrive_time` timestamp NULL DEFAULT NULL COMMENT '到货时间',
  `status` tinyint(4) DEFAULT '0' COMMENT '状态 0:未付款 1:未发货 2:待收货 3:待评论 4:退货 5:已完成 6:订单失效 7:订单  关闭 8:删除订单 9:拼团中 10:拼团失败-未退款 11:拼团失败-已退款',
  `coupon_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subtraction_id` int(11) DEFAULT NULL COMMENT '满减活动ID',
  `consumer_money` int(11) DEFAULT '0' COMMENT '消费金',
  `coupon_activity_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `drawid` int(11) DEFAULT '0' COMMENT '活动ID',
  `otype` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ptcode` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pid` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ptstatus` smallint(6) DEFAULT NULL COMMENT '拼团状态:0,未付款 1,拼团中 2,拼团成功 3,拼团失败',
  `groupman` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `refundsNo` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `trade_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_anonymous` int(1) DEFAULT '0' COMMENT '是否匿名(0,否  1.是',
  `logistics_service` int(1) DEFAULT NULL COMMENT '物流服务',
  `overall_evaluation` int(1) DEFAULT NULL COMMENT '总体评价',
  `spz_price` decimal(10,2) DEFAULT NULL COMMENT '商品总价',
  `reduce_price` decimal(10,2) DEFAULT NULL COMMENT '查询出的满减金额',
  `coupon_price` decimal(10,2) DEFAULT NULL COMMENT '查询出的优惠券金额',
  `red_packet` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `allow` int(8) DEFAULT '0' COMMENT '积分',
  `parameter` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `source` tinyint(4) NOT NULL DEFAULT '1' COMMENT '来源 1.小程序 2.app',
  `delivery_status` int(1) DEFAULT '0' COMMENT '提醒发货',
  `readd` int(2) NOT NULL DEFAULT '0' COMMENT '是否已读（0，未读  1 已读）',
  `remind` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '提醒\r\n\r\n发货时间间隔',
  `offset_balance` decimal(10,2) DEFAULT NULL COMMENT '抵扣余额',
  `mch_id` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `zhekou` decimal(10,2) NOT NULL COMMENT '分销折扣',
  `grade_rate` decimal(10,2) DEFAULT NULL COMMENT '会员等级折扣',
  `grade_score` int(11) DEFAULT NULL COMMENT '会员购物积分',
  `grade_fan` decimal(12,2) DEFAULT NULL COMMENT '会员返现金额',
  `p_sNo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `activity_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bargain_id` int(11) NOT NULL DEFAULT '0' COMMENT '砍价活动id',
  `comm_discount` decimal(10,2) NOT NULL COMMENT '分销折扣',
  `real_sno` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `remarks` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `self_lifting` tinyint(4) DEFAULT '0' COMMENT '自提 0.配送 1.自提',
  `extraction_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `extraction_code_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_put` tinyint(4) DEFAULT '0' COMMENT '是否发放佣金 0.否 1.是',
  `z_freight` decimal(12,2) DEFAULT NULL COMMENT '总运费',
  `preferential_amount` decimal(12,2) DEFAULT NULL COMMENT '优惠金额',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.回收',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `sNo` (`sNo`(191)) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='拼团订单记录表';

-- ----------------------------
-- Records of lkt_go_group_order
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_go_group_order_details
-- ----------------------------
DROP TABLE IF EXISTS `lkt_go_group_order_details`;
CREATE TABLE `lkt_go_group_order_details` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) DEFAULT '0' COMMENT '商城id',
  `user_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `p_id` int(11) DEFAULT NULL COMMENT '产品id',
  `p_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `p_price` decimal(12,2) DEFAULT NULL COMMENT '产品价格',
  `num` int(11) DEFAULT NULL COMMENT '数量',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `r_sNo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `deliver_time` timestamp NULL DEFAULT NULL COMMENT '发货时间',
  `arrive_time` timestamp NULL DEFAULT NULL COMMENT '到货时间',
  `r_status` tinyint(4) DEFAULT '0' COMMENT ' ''状态 0：未付款 1：未发货 2：待收货 3：待评论 4：退货 5:已完成 6 订单关闭 9拼团中 10 拼团失败-未退款 11 拼团失败-已退款''',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `reason` char(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `re_type` tinyint(4) DEFAULT '0' COMMENT '退款类型 1:退货退款  2:退款 3:售后',
  `re_apply_money` float(12,2) DEFAULT NULL COMMENT '用户申请退款金额',
  `re_money` float(12,2) DEFAULT NULL COMMENT '退款金额',
  `real_money` decimal(12,2) DEFAULT NULL COMMENT '实际退款金额',
  `re_time` datetime DEFAULT NULL COMMENT '申请退款时间',
  `re_photo` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `r_content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `r_type` tinyint(4) DEFAULT '100' COMMENT '类型 100:不在退货退款状态0:审核中 1:同意并让用户寄回 2:拒绝(退货退款) 3:用户已快递 4:收到寄回商品,同意并退款 5：拒绝并退回商品 8:拒绝(退款) 9:同意并退款 10:拒绝(售后)11:同意并且寄回商品 12售后结束',
  `express_id` int(255) DEFAULT NULL COMMENT '快递公司id',
  `courier_num` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `express_type` tinyint(4) DEFAULT '1' COMMENT '发货类型 1.手动发货 2.自动发货',
  `freight` decimal(12,2) DEFAULT NULL COMMENT '运费',
  `size` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sid` char(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `invoice` tinyint(4) DEFAULT '0' COMMENT '发货单打印 0.否 1.是',
  `express` tinyint(4) DEFAULT '0' COMMENT '快递单打印 0.否 1.是',
  `exchange_num` int(11) DEFAULT '0' COMMENT '换货次数',
  `coupon_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `after_discount` decimal(12,2) DEFAULT NULL COMMENT '优惠后的金额',
  `settlement_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '订单结算标识 0未结算 1已结算',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.回收',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `r_sNo` (`r_sNo`(191)) USING BTREE,
  KEY `sid` (`sid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='拼团订单详情表';

-- ----------------------------
-- Records of lkt_go_group_order_details
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_group_activity
-- ----------------------------
DROP TABLE IF EXISTS `lkt_group_activity`;
CREATE TABLE `lkt_group_activity` (
  `id` int(1) NOT NULL AUTO_INCREMENT COMMENT '活动id',
  `name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `status` int(11) NOT NULL DEFAULT '0' COMMENT '拼团状态 0=未开始 1=拼团中 2=已结束',
  `start_date` datetime NOT NULL COMMENT '开始时间',
  `end_date` datetime NOT NULL COMMENT '结束时间',
  `is_custom` tinyint(4) DEFAULT '0' COMMENT '时间是否自定义 0不是 1是',
  `team_rule` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `team_limit` int(11) NOT NULL DEFAULT '0' COMMENT '团长是否可参团',
  `goods_limit` int(11) NOT NULL DEFAULT '0' COMMENT '同一商品参团限制开关',
  `is_show` int(11) NOT NULL DEFAULT '1' COMMENT '是否显示',
  `add_date` datetime NOT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '删除标识',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='拼团活动表';

-- ----------------------------
-- Records of lkt_group_activity
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_group_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_group_config`;
CREATE TABLE `lkt_group_config` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `end_time` int(11) NOT NULL DEFAULT '0' COMMENT '成团倒计时 0=不计时',
  `open_limit` int(11) NOT NULL DEFAULT '0' COMMENT '开团限制数量 0=不限制',
  `join_limit` int(11) NOT NULL DEFAULT '0' COMMENT '参团限制数量 0=不限制',
  `rule_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_date` datetime NOT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='拼团配置表';

-- ----------------------------
-- Records of lkt_group_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_group_goods
-- ----------------------------
DROP TABLE IF EXISTS `lkt_group_goods`;
CREATE TABLE `lkt_group_goods` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '活动商品id',
  `activity_id` int(11) NOT NULL DEFAULT '0' COMMENT '活动id',
  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `add_date` datetime NOT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '删除标识',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='拼团商品表';

-- ----------------------------
-- Records of lkt_group_goods
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_group_open
-- ----------------------------
DROP TABLE IF EXISTS `lkt_group_open`;
CREATE TABLE `lkt_group_open` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `activity_id` int(11) NOT NULL DEFAULT '0' COMMENT '活动id',
  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `attr_id` int(11) NOT NULL COMMENT '规格id',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `team_num` int(11) NOT NULL COMMENT '团队数量',
  `team_commission` decimal(12,2) NOT NULL COMMENT '团长佣金',
  `status` int(11) NOT NULL DEFAULT '0' COMMENT '商品拼团状态 0=拼团中 1=拼团成功 2=拼团失败',
  `sno` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_settlement` int(11) NOT NULL DEFAULT '0' COMMENT '是否已结算',
  `add_date` datetime NOT NULL COMMENT '添加时间',
  `end_date` datetime NOT NULL COMMENT '拼团结束时间',
  `update_date` datetime DEFAULT NULL COMMENT '修改时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '删除标识',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='开团表';

-- ----------------------------
-- Records of lkt_group_open
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_group_open_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_group_open_record`;
CREATE TABLE `lkt_group_open_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `open_id` int(11) NOT NULL DEFAULT '0' COMMENT '开团id',
  `goods_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品id',
  `attr_id` int(11) NOT NULL COMMENT '规格id',
  `attr_price` decimal(12,2) NOT NULL COMMENT '零售价',
  `price` decimal(12,2) NOT NULL COMMENT '参团金额',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sno` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` datetime NOT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '删除标识',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='拼团详情表';

-- ----------------------------
-- Records of lkt_group_open_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_group_order_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_group_order_config`;
CREATE TABLE `lkt_group_order_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `order_after` int(3) NOT NULL DEFAULT '604800' COMMENT '订单售后时间 (单位秒)',
  `auto_the_goods` int(11) NOT NULL DEFAULT '7' COMMENT '自动收货时间',
  `auto_good_comment_day` int(5) NOT NULL DEFAULT '0' COMMENT '自动评价设置几后自动好评',
  `auto_good_comment_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `is_open` tinyint(4) DEFAULT '0' COMMENT '是否开启拼团插件 插件状态 0关闭 1开启',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='拼团订单设置';

-- ----------------------------
-- Records of lkt_group_order_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_group_product
-- ----------------------------
DROP TABLE IF EXISTS `lkt_group_product`;
CREATE TABLE `lkt_group_product` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `group_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `attr_id` int(11) NOT NULL COMMENT '规格id',
  `product_id` int(11) unsigned DEFAULT NULL COMMENT '产品id',
  `group_level` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `group_data` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `starttime` timestamp NULL DEFAULT NULL COMMENT '开始日期',
  `endtime` timestamp NULL DEFAULT NULL COMMENT '结束日期',
  `activity_no` int(11) NOT NULL COMMENT '活动编号',
  `g_status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '活动状态: 1.未开始 2.活动中 3.已结束',
  `is_show` tinyint(4) NOT NULL DEFAULT '1' COMMENT '是否显示',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  `is_copy` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否为复制 1为复制 0不是复制',
  `platform_activities_id` int(11) NOT NULL DEFAULT '0' COMMENT '平台活动id',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺id',
  `audit_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审核状态',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `num` int(11) DEFAULT '0' COMMENT '活动库存',
  `sales_volume` int(11) DEFAULT '0' COMMENT '活动销量',
  `price` decimal(12,2) DEFAULT NULL COMMENT '成本价',
  `addtime` datetime NOT NULL COMMENT '申请时间',
  `free_freight` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否免邮(1 是 0 否)默认0',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='拼团产品';

-- ----------------------------
-- Records of lkt_group_product
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_guide
-- ----------------------------
DROP TABLE IF EXISTS `lkt_guide`;
CREATE TABLE `lkt_guide` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `image` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `source` tinyint(4) DEFAULT '0' COMMENT '来源 1:小程序 2:APP',
  `type` int(11) DEFAULT NULL COMMENT '类型 0=安装 1=启动',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='引导图表';

-- ----------------------------
-- Records of lkt_guide
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_guide_menu
-- ----------------------------
DROP TABLE IF EXISTS `lkt_guide_menu`;
CREATE TABLE `lkt_guide_menu` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) DEFAULT '0' COMMENT '商城ID',
  `role_id` int(11) DEFAULT '0' COMMENT '角色ID',
  `menu_id` int(11) DEFAULT '0' COMMENT '菜单ID',
  `is_display` tinyint(4) DEFAULT '1' COMMENT '是否显示 0.不显示 1.显示',
  `guide_sort` int(11) DEFAULT '0' COMMENT '导览排序',
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `menu_id_idx` (`menu_id`) USING BTREE,
  KEY `role_id_idx` (`role_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=157927 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='导览菜单';

-- ----------------------------
-- Records of lkt_guide_menu
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_hotkeywords
-- ----------------------------
DROP TABLE IF EXISTS `lkt_hotkeywords`;
CREATE TABLE `lkt_hotkeywords` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `store_id` int(11) DEFAULT NULL COMMENT '商城ID',
  `is_open` tinyint(4) DEFAULT '0' COMMENT '是否开启 0.未开启 1.\r\n\r\n开启',
  `num` int(11) DEFAULT '0' COMMENT '关键词上限',
  `keyword` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `mch_keyword` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of lkt_hotkeywords
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_img_group
-- ----------------------------
DROP TABLE IF EXISTS `lkt_img_group`;
CREATE TABLE `lkt_img_group` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '分组id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sort` int(11) DEFAULT '100' COMMENT '排序',
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `is_default` tinyint(2) NOT NULL DEFAULT '0' COMMENT '0不是默认 1默认',
  `supplier_id` int(11) DEFAULT NULL COMMENT '供应商id',
  `mch_id` int(11) DEFAULT NULL COMMENT '店铺ID',
  `type` tinyint(4) DEFAULT '1' COMMENT '资源类型，1图片，2视频',
  `is_show` tinyint(4) DEFAULT '1' COMMENT '该分类是否常驻显示，1为不常驻显示，2为常驻显示',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='图片分组表';

-- ----------------------------
-- Records of lkt_img_group
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_import_log
-- ----------------------------
DROP TABLE IF EXISTS `lkt_import_log`;
CREATE TABLE `lkt_import_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '导入类型1商品导入2评论导入',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '导入状态1成功2失败',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_time` datetime NOT NULL COMMENT '导入时间',
  `mch_id` int(11) DEFAULT NULL COMMENT '操作店铺id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=108 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='文件导入记录表';

-- ----------------------------
-- Records of lkt_import_log
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_integral_class
-- ----------------------------
DROP TABLE IF EXISTS `lkt_integral_class`;
CREATE TABLE `lkt_integral_class` (
  `cid` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '分类id',
  `sid` int(11) NOT NULL COMMENT '上级id',
  `pname` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `img` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `level` int(11) NOT NULL COMMENT '级别',
  `sort` int(11) DEFAULT '100' COMMENT '排序',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `recycle` tinyint(4) DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  PRIMARY KEY (`cid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='积分商城分类';

-- ----------------------------
-- Records of lkt_integral_class
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_integral_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_integral_config`;
CREATE TABLE `lkt_integral_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `bg_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `status` int(5) NOT NULL DEFAULT '0' COMMENT '插件状态 0关闭 1开启',
  `score_ratio` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '积分支付比例',
  `same_piece` int(11) DEFAULT NULL COMMENT '同件n件包邮',
  `package_settings` int(11) NOT NULL DEFAULT '0' COMMENT '多件包邮设置 0.未开启 1.开启',
  `order_failure` int(11) NOT NULL DEFAULT '0' COMMENT '订单失效 (单位 秒)',
  `order_after` int(3) NOT NULL DEFAULT '604800' COMMENT '订单售后时间 (单位秒)',
  `auto_the_goods` int(11) NOT NULL DEFAULT '604800' COMMENT '自动收货时间',
  `deliver_remind` int(11) NOT NULL DEFAULT '3600' COMMENT '提醒发货限制 间隔(单位 秒)',
  `auto_good_comment_day` int(5) NOT NULL DEFAULT '0' COMMENT '自动评价设置几后自动好评',
  `auto_good_comment_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '自动评价内容',
  `proportion` decimal(10,0) DEFAULT NULL COMMENT '积分比例(购物赠送积分=购物交易金额*赠送比例)',
  `give_status` int(11) DEFAULT '0' COMMENT '发放状态(0=收货后 1=付款后)',
  `overdue_time` int(11) DEFAULT '604800' COMMENT '积分有效时间从积分获取后开始计算，至 x 失效',
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `ams_time` int(11) DEFAULT '0' COMMENT '收货后多少天返回积分，至 x 失效',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='积分设置表';

-- ----------------------------
-- Records of lkt_integral_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_integral_goods
-- ----------------------------
DROP TABLE IF EXISTS `lkt_integral_goods`;
CREATE TABLE `lkt_integral_goods` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0',
  `goods_id` int(11) NOT NULL COMMENT '商品ID',
  `attr_id` int(11) DEFAULT NULL COMMENT '属性id',
  `integral` int(11) NOT NULL DEFAULT '0' COMMENT '兑换所需积分',
  `money` decimal(11,2) NOT NULL COMMENT '兑换所需余额',
  `num` int(11) NOT NULL DEFAULT '0' COMMENT '库存数量',
  `max_num` int(11) NOT NULL DEFAULT '0' COMMENT '上架库存',
  `sort` int(11) NOT NULL DEFAULT '1' COMMENT '排序',
  `is_delete` smallint(6) NOT NULL DEFAULT '0' COMMENT '是否删除:0否   1是',
  `add_time` datetime DEFAULT NULL COMMENT '添加时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '上架状态 1待上架， 2已上架 ， 3已下架',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=313 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='积分商城商品表';

-- ----------------------------
-- Records of lkt_integral_goods
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_invoice_header
-- ----------------------------
DROP TABLE IF EXISTS `lkt_invoice_header`;
CREATE TABLE `lkt_invoice_header` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` int(11) NOT NULL DEFAULT '1' COMMENT '抬头类型 1.企业 2.个人',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `company_tax_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `register_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `register_phone` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `deposit_bank` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bank_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_default` int(10) NOT NULL DEFAULT '0' COMMENT '是否默认 0.否 1.是',
  `recovery` int(10) NOT NULL DEFAULT '0' COMMENT '是否回收 0.否 1.是',
  `add_time` datetime NOT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='发票抬头表';

-- ----------------------------
-- Records of lkt_invoice_header
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_invoice_info
-- ----------------------------
DROP TABLE IF EXISTS `lkt_invoice_info`;
CREATE TABLE `lkt_invoice_info` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` int(11) NOT NULL DEFAULT '1' COMMENT '抬头类型 1.企业 2.个人',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `company_tax_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `invoice_header` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `s_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `invoice_amount` decimal(10,2) NOT NULL COMMENT '发票金额',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `invoice_status` int(10) NOT NULL DEFAULT '1' COMMENT '发票状态 1.申请中 2.已完成 3.已撤销',
  `file` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `file_time` datetime DEFAULT NULL COMMENT '上传发票文件时间',
  `recovery` int(10) NOT NULL DEFAULT '0' COMMENT '是否回收 0.否 1.是',
  `add_time` datetime NOT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='发票信息表';

-- ----------------------------
-- Records of lkt_invoice_info
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_jump_path
-- ----------------------------
DROP TABLE IF EXISTS `lkt_jump_path`;
CREATE TABLE `lkt_jump_path` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) DEFAULT '0' COMMENT '商城ID',
  `mch_id` int(11) DEFAULT NULL COMMENT '店铺ID',
  `type0` tinyint(2) DEFAULT '0' COMMENT '跳转类型 1.分类 2.商品 3.店铺',
  `type` tinyint(2) NOT NULL DEFAULT '1' COMMENT '类型 1.移动端 2.PC商城',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(2) NOT NULL DEFAULT '0' COMMENT '是否启用 0.不开启 1.开启',
  `parameter_status` tinyint(2) NOT NULL DEFAULT '0' COMMENT '是否有参数 0.没有参数 1.有参数',
  `parameter` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `sid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `lang_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'zh_CN' COMMENT '语种编码默认中文简体',
  `country_num` int(11) DEFAULT '156' COMMENT '所属国家',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=826 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='路径跳转表';

-- ----------------------------
-- Records of lkt_jump_path
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_lang
-- ----------------------------
DROP TABLE IF EXISTS `lkt_lang`;
CREATE TABLE `lkt_lang` (
  `lang_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '语音名称',
  `lang_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '语言编码',
  `show_num` int(11) DEFAULT NULL COMMENT '排序位置',
  `is_show` int(11) DEFAULT '1' COMMENT '是否显示 1显示2不显示',
  `recycle` int(11) DEFAULT '1' COMMENT '是否回收 1不回收 2 回收',
  `op_time` timestamp NULL DEFAULT NULL COMMENT '操作时间',
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `lang_code` (`lang_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='国际化语种信息表';

-- ----------------------------
-- Records of lkt_lang
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_level_update
-- ----------------------------
DROP TABLE IF EXISTS `lkt_level_update`;
CREATE TABLE `lkt_level_update` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '途径 1规则 2礼包 3系统',
  `old_level` int(11) NOT NULL COMMENT '变更前等级',
  `up_level` int(11) NOT NULL COMMENT '变更后等级',
  `add_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '变更时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='会员等级变更记录表';

-- ----------------------------
-- Records of lkt_level_update
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_living_anchor
-- ----------------------------
DROP TABLE IF EXISTS `lkt_living_anchor`;
CREATE TABLE `lkt_living_anchor` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `commission` decimal(10,2) NOT NULL COMMENT '佣金金额',
  `onlyamount` decimal(10,2) NOT NULL COMMENT '累计佣金',
  `tx_commission` decimal(10,2) NOT NULL COMMENT '可提现佣金',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='主播表';

-- ----------------------------
-- Records of lkt_living_anchor
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_living_audience
-- ----------------------------
DROP TABLE IF EXISTS `lkt_living_audience`;
CREATE TABLE `lkt_living_audience` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `living_id` int(11) NOT NULL DEFAULT '0' COMMENT '直播间ID',
  `start_time` timestamp NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` timestamp NULL DEFAULT NULL COMMENT '结束时间',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  `sc` int(11) NOT NULL DEFAULT '0' COMMENT '观看时长',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=367 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='直播间观众';

-- ----------------------------
-- Records of lkt_living_audience
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_living_comment
-- ----------------------------
DROP TABLE IF EXISTS `lkt_living_comment`;
CREATE TABLE `lkt_living_comment` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `living_id` int(11) NOT NULL DEFAULT '0' COMMENT '直播间ID',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `comment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `p_id` int(11) NOT NULL DEFAULT '0' COMMENT '上级ID',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  `comment_type` int(11) NOT NULL DEFAULT '0' COMMENT '评论类型 1评论，2关注，3点赞,4加入',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='直播间评论';

-- ----------------------------
-- Records of lkt_living_comment
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_living_commission
-- ----------------------------
DROP TABLE IF EXISTS `lkt_living_commission`;
CREATE TABLE `lkt_living_commission` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `living_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `s_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `commission` decimal(10,2) NOT NULL COMMENT '佣金金额',
  `status` int(11) NOT NULL COMMENT '结算状态（101未发放，100已发放）',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='佣金表';

-- ----------------------------
-- Records of lkt_living_commission
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_living_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_living_config`;
CREATE TABLE `lkt_living_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `is_open` int(11) NOT NULL DEFAULT '0' COMMENT '获取是否开启插件 0-不开启 1-开启',
  `mch_is_open` int(11) NOT NULL DEFAULT '0' COMMENT '店铺端入口设置 0-不开启 1-开启',
  `push_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `play_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `agree_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `agree_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  `license_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `license_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='直播配置';

-- ----------------------------
-- Records of lkt_living_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_living_follow_list
-- ----------------------------
DROP TABLE IF EXISTS `lkt_living_follow_list`;
CREATE TABLE `lkt_living_follow_list` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `anchor_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户关注列表';

-- ----------------------------
-- Records of lkt_living_follow_list
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_living_product
-- ----------------------------
DROP TABLE IF EXISTS `lkt_living_product`;
CREATE TABLE `lkt_living_product` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `living_id` int(11) NOT NULL DEFAULT '0' COMMENT '直播间ID',
  `pro_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `config_id` int(11) NOT NULL DEFAULT '0' COMMENT '规格ID',
  `live_price` decimal(12,2) NOT NULL COMMENT '直播价格',
  `total_num` int(11) NOT NULL DEFAULT '0' COMMENT '上架库存',
  `num` int(11) NOT NULL DEFAULT '0' COMMENT '剩余库存',
  `sort` int(11) NOT NULL DEFAULT '1' COMMENT '排序',
  `xl_num` int(11) NOT NULL DEFAULT '0' COMMENT '销量',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  `represent` int(11) NOT NULL DEFAULT '0' COMMENT '是否在讲解（每个直播间只能有一个讲解的产品，默认0不讲解）',
  `sort_num` int(11) NOT NULL DEFAULT '0' COMMENT '序号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=681 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='直播间产品';

-- ----------------------------
-- Records of lkt_living_product
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_living_room
-- ----------------------------
DROP TABLE IF EXISTS `lkt_living_room`;
CREATE TABLE `lkt_living_room` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `living_theme` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `living_description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `start_time` timestamp NULL DEFAULT NULL COMMENT '直播开始时间',
  `living_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `end_time` timestamp NULL DEFAULT NULL COMMENT '直播结束时间',
  `living_status` int(11) NOT NULL DEFAULT '0' COMMENT '直播的状态，0：预约中，1：直播中，2：已结束，3：已取消',
  `living_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `living_num` int(11) NOT NULL DEFAULT '0' COMMENT '直播间观看人数',
  `living_review_num` int(11) NOT NULL DEFAULT '0' COMMENT '直播间评论数',
  `push_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `play_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `like_num` int(11) NOT NULL DEFAULT '0' COMMENT '点赞数',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `living_fans_num` int(11) NOT NULL DEFAULT '0' COMMENT '观看粉丝数',
  `fans_num` int(11) NOT NULL DEFAULT '0' COMMENT '新增粉丝数',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='直播间';

-- ----------------------------
-- Records of lkt_living_room
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_living_sensitive
-- ----------------------------
DROP TABLE IF EXISTS `lkt_living_sensitive`;
CREATE TABLE `lkt_living_sensitive` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `word` mediumtext CHARACTER SET utf8 COLLATE utf8_bin COMMENT '敏感词',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `store_id` int(11) DEFAULT NULL COMMENT '商城id',
  `recycle` int(11) DEFAULT '0' COMMENT '逻辑删除标志',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of lkt_living_sensitive
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_living_user_like
-- ----------------------------
DROP TABLE IF EXISTS `lkt_living_user_like`;
CREATE TABLE `lkt_living_user_like` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `living_id` int(11) NOT NULL DEFAULT '0' COMMENT '直播间ID',
  `dzs_num` int(11) NOT NULL DEFAULT '0' COMMENT '点赞数',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='我的点赞';

-- ----------------------------
-- Records of lkt_living_user_like
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_map
-- ----------------------------
DROP TABLE IF EXISTS `lkt_map`;
CREATE TABLE `lkt_map` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '地区id',
  `district_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '地区名称',
  `district_pid` int(11) DEFAULT NULL COMMENT '父地区id',
  `district_show_order` int(11) DEFAULT NULL COMMENT '显示排序',
  `district_level` int(11) DEFAULT NULL COMMENT '层级',
  `district_childcount` int(11) DEFAULT NULL COMMENT '子地区数（未用）',
  `district_delete` int(11) DEFAULT '0' COMMENT '是否删除（未用）',
  `district_num` int(11) DEFAULT '0' COMMENT '（未用）',
  `district_country_num` int(11) DEFAULT NULL COMMENT '国家编码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3436 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='地址信息';

-- ----------------------------
-- Records of lkt_map
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch`;
CREATE TABLE `lkt_mch` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `shop_information` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `shop_range` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `realname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ID_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `cpc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '区号',
  `tel` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sheng` char(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `shi` char(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `xian` char(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `shop_nature` tinyint(3) NOT NULL DEFAULT '0' COMMENT '店铺性质：0.个人 1.企业',
  `business_license` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '申请时间',
  `review_time` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `review_status` tinyint(3) NOT NULL DEFAULT '0' COMMENT '审核状态：0.待审核 1.审核通过 2.审核不通过',
  `review_result` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `integral_money` decimal(12,0) NOT NULL COMMENT '商户积分',
  `account_money` decimal(12,2) NOT NULL COMMENT '商户余额',
  `collection_num` int(11) DEFAULT '0' COMMENT '收藏数量',
  `is_open` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否营业：0.未营业 1.营业中 2.打烊',
  `is_lock` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否被系统关闭：0.否 1.是',
  `confines` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mch_service` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `business_hours` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `roomid` int(11) unsigned DEFAULT '0',
  `old_roomid` int(11) DEFAULT '0' COMMENT '旧房间ID',
  `longitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `latitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `cashable_money` decimal(12,2) NOT NULL COMMENT '可取现金额',
  `recovery` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否回收 0.未回收 1.回收',
  `is_invoice` int(11) NOT NULL DEFAULT '0' COMMENT '是否支持开票 0.否 1.是',
  `cid` int(11) NOT NULL DEFAULT '0' COMMENT '分类id',
  `poster_img` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `head_img` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `collection_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pc_mch_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_open_coupon` int(11) DEFAULT '1' COMMENT '是否开启店铺主页领卷人口',
  `last_login_time` datetime DEFAULT NULL COMMENT '最后登录时间',
  `sub_mch_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sub_app_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_self_delivery` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否支持商家自配 0.否 1.是',
  `new_user_order_num` int(11) DEFAULT '0' COMMENT '新增下单客户数',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商户';

-- ----------------------------
-- Records of lkt_mch
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_account_log
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_account_log`;
CREATE TABLE `lkt_mch_account_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `integral` int(12) DEFAULT '0' COMMENT '积分',
  `integral_money` decimal(12,0) DEFAULT NULL COMMENT '商户积分',
  `price` decimal(12,2) NOT NULL COMMENT '金额',
  `account_money` decimal(12,2) NOT NULL COMMENT '商户余额',
  `status` tinyint(3) NOT NULL DEFAULT '1' COMMENT '状态：1.入账 2.出账',
  `type` tinyint(3) NOT NULL DEFAULT '1' COMMENT '类型：1.订单 2.退款 3.提现 4.保证金 5.供应商订单',
  `addtime` timestamp NULL DEFAULT NULL COMMENT '时间',
  `remake` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=478 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='入驻商户账户收支记录表';

-- ----------------------------
-- Records of lkt_mch_account_log
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_admin
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_admin`;
CREATE TABLE `lkt_mch_admin` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) DEFAULT '0' COMMENT '商城ID',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  `mch_store_id` int(11) DEFAULT '0' COMMENT '店铺门店ID',
  `ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `access_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `account_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `recycle` tinyint(1) DEFAULT '0' COMMENT '回收站 0:不回收 1:回收',
  `last_time` datetime DEFAULT NULL COMMENT '最后一次登录时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺管理员';

-- ----------------------------
-- Records of lkt_mch_admin
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_admin_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_admin_record`;
CREATE TABLE `lkt_mch_admin_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) DEFAULT '0' COMMENT '商城ID',
  `administrators_id` int(11) DEFAULT '0' COMMENT '管理员ID',
  `sNo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺管理员核销记录表';

-- ----------------------------
-- Records of lkt_mch_admin_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_browse
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_browse`;
CREATE TABLE `lkt_mch_browse` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `event` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4484 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺浏览记录表';

-- ----------------------------
-- Records of lkt_mch_browse
-- ----------------------------
