-- ----------------------------
-- Records of lkt_mch_class
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_config`;
CREATE TABLE `lkt_mch_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `settlement` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `min_charge` decimal(12,2) DEFAULT NULL COMMENT '最低提现金额\r\n\r\n',
  `max_charge` decimal(12,2) DEFAULT NULL COMMENT '最大提现金额\r\n\r\n',
  `service_charge` decimal(12,2) DEFAULT NULL COMMENT '手续费',
  `illustrate` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `agreement` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `delete_settings` int(11) DEFAULT '0' COMMENT '删除设置',
  `commodity_setup` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_display` tinyint(4) DEFAULT '0' COMMENT '是否显示 0.不显示 1.显示',
  `promise_switch` int(11) NOT NULL DEFAULT '0' COMMENT '保证金开关',
  `promise_amt` decimal(10,2) DEFAULT NULL COMMENT '保证金金额',
  `promise_text` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `package_settings` int(11) DEFAULT '0' COMMENT '包邮设置',
  `same_piece` int(11) DEFAULT '0' COMMENT '同件',
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `same_order` int(11) DEFAULT '0' COMMENT '同单',
  `poster_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `head_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `auto_examine` int(11) DEFAULT '1' COMMENT '店铺自动审核天数',
  `auto_log_off` int(11) DEFAULT '0' COMMENT '自动注销时间(月)',
  `withdrawal_time_open` int(5) DEFAULT '0' COMMENT '提现时间开关 0.不限制 1.指定日期 2.指定时间段',
  `withdrawal_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商户配置表';

-- ----------------------------
-- Records of lkt_mch_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_distribution
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_distribution`;
CREATE TABLE `lkt_mch_distribution` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺id',
  `d_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `relationship` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `proportion` decimal(12,2) NOT NULL COMMENT '分账比例',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `isAccounts` int(11) NOT NULL DEFAULT '0' COMMENT '是否分账',
  `accountsSet` int(11) NOT NULL DEFAULT '0' COMMENT '分账账号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺分账账户信息';

-- ----------------------------
-- Records of lkt_mch_distribution
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_distribution_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_distribution_record`;
CREATE TABLE `lkt_mch_distribution_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺id',
  `sub_mch_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `wx_order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `out_order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `total_amount` decimal(12,2) NOT NULL COMMENT '分账总金额',
  `amount` decimal(12,2) NOT NULL COMMENT '分账金额',
  `proportion` decimal(12,2) DEFAULT NULL COMMENT '分账比例',
  `r_type` int(10) NOT NULL DEFAULT '1' COMMENT '记录类型 1.分账 2.回退',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `is_platform_account` tinyint(4) DEFAULT '0' COMMENT '是否是平台 0.不是 1.是',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=664852 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺分账记录信息';

-- ----------------------------
-- Records of lkt_mch_distribution_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_order_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_order_record`;
CREATE TABLE `lkt_mch_order_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '店铺交易数据id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `count_day` timestamp NULL DEFAULT NULL COMMENT '日期',
  `order_number` int(11) NOT NULL COMMENT '订单数量',
  `money` decimal(10,2) NOT NULL COMMENT '金额',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7871 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺交易数据表';

-- ----------------------------
-- Records of lkt_mch_order_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_promise
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_promise`;
CREATE TABLE `lkt_mch_promise` (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `orderNo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `promise_amt` decimal(10,2) NOT NULL COMMENT '保证金金额',
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '保证金状态 1=已交 2=已退还',
  `pay_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_return_pay` int(255) NOT NULL DEFAULT '0' COMMENT '是否退还',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `update_date` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺保证金记录表';

-- ----------------------------
-- Records of lkt_mch_promise
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_statistics
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_statistics`;
CREATE TABLE `lkt_mch_statistics` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '店铺数据汇总id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `pending_shipment` int(11) NOT NULL DEFAULT '0' COMMENT '待发货订单',
  `obligation` int(11) NOT NULL DEFAULT '0' COMMENT '待付款订单',
  `refund_order` int(11) NOT NULL DEFAULT '0' COMMENT '退款订单',
  `audit_order` int(11) NOT NULL DEFAULT '0' COMMENT '待审核订单',
  `audit_pro` int(11) NOT NULL DEFAULT '0' COMMENT '待审核商品',
  `ckbz_pro` int(11) NOT NULL DEFAULT '0' COMMENT '库存不足商品',
  `djs_order` int(11) NOT NULL DEFAULT '0' COMMENT '待结算订单',
  `dsh_order` int(11) NOT NULL DEFAULT '0' COMMENT '待收货订单',
  `sj_pro` int(11) NOT NULL DEFAULT '0' COMMENT '上架商品',
  `xj_pro` int(11) NOT NULL DEFAULT '0' COMMENT '下架商品',
  `pro_class` int(11) NOT NULL DEFAULT '0' COMMENT '商品分类',
  `pro_brand` int(11) NOT NULL DEFAULT '0' COMMENT '商品品牌',
  `sale_pro_sku` int(11) NOT NULL DEFAULT '0' COMMENT '销售商品sku',
  `pro_sku` int(11) NOT NULL DEFAULT '0' COMMENT '商品sku数量',
  `customer_num` int(11) NOT NULL DEFAULT '0' COMMENT '总客单数量',
  `attention_user_num` int(11) NOT NULL DEFAULT '0' COMMENT '关注的客户',
  `access_user_num` int(11) NOT NULL DEFAULT '0' COMMENT '访问的客户',
  `new_pay_user` int(11) NOT NULL DEFAULT '0' COMMENT '新增下单客户',
  `djs_money` decimal(10,2) NOT NULL COMMENT '待结算金额',
  `ytx_money` decimal(10,2) NOT NULL COMMENT '已提现金额',
  `return_money` decimal(10,2) NOT NULL COMMENT '退款金额',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `recycle` int(11) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7799 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺数据汇总表';

-- ----------------------------
-- Records of lkt_mch_statistics
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_store
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_store`;
CREATE TABLE `lkt_mch_store` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mobile` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `business_hours` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `sheng` char(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `shi` char(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `xian` char(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `longitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `latitude` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_default` tinyint(4) DEFAULT '0' COMMENT '是否默认 0.不默认 1.默认',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺门店表';

-- ----------------------------
-- Records of lkt_mch_store
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_mch_store_write
-- ----------------------------
DROP TABLE IF EXISTS `lkt_mch_store_write`;
CREATE TABLE `lkt_mch_store_write` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `mch_store_id` int(11) NOT NULL COMMENT '门店id',
  `start_time` timestamp NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` timestamp NULL DEFAULT NULL COMMENT '结束时间',
  `period` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `write_off_num` int(11) DEFAULT '0' COMMENT '可预约核销次数 0无限制',
  `off_num` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='虚拟商品订单核销表';

-- ----------------------------
-- Records of lkt_mch_store_write
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_member_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_member_config`;
CREATE TABLE `lkt_member_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `is_open` int(11) NOT NULL DEFAULT '0' COMMENT '会员插件开关 0.关 1.开',
  `open_config` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `birthday_open` int(10) NOT NULL DEFAULT '0' COMMENT '会员生日特权开关 0.关 1.开',
  `points_multiple` int(10) DEFAULT '1' COMMENT '积分倍数',
  `bonus_points_open` int(10) NOT NULL DEFAULT '0' COMMENT '会员赠送积分开关 0.关 1.开',
  `bonus_points_config` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `member_discount` decimal(10,2) NOT NULL COMMENT '会员打折率',
  `renew_open` int(10) NOT NULL DEFAULT '0' COMMENT '续费提醒开关 0.关 1.开',
  `renew_day` int(10) DEFAULT NULL COMMENT '开始续费提醒天数',
  `member_equity` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_time` datetime NOT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='会员设置表';

-- ----------------------------
-- Records of lkt_member_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_member_pro
-- ----------------------------
DROP TABLE IF EXISTS `lkt_member_pro`;
CREATE TABLE `lkt_member_pro` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `pro_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品id',
  `recovery` int(10) NOT NULL DEFAULT '0' COMMENT '是否回收 0.否 1是',
  `add_time` datetime DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='会员商品表';

-- ----------------------------
-- Records of lkt_member_pro
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_menu
-- ----------------------------
DROP TABLE IF EXISTS `lkt_menu`;
CREATE TABLE `lkt_menu` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `main_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` int(11) NOT NULL COMMENT '1=门店id 2=店铺id 3=商城id',
  `sid` int(11) NOT NULL DEFAULT '0',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `level` int(11) DEFAULT '1' COMMENT '菜单等级',
  `logo` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `checked_logo` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `text` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_display` int(11) DEFAULT '0' COMMENT '是否禁用 1=是 0=否',
  `sort` int(11) DEFAULT '0' COMMENT '排序序号',
  `add_date` datetime DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime DEFAULT NULL COMMENT '修改时间',
  `lang_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'zh_CN' COMMENT '语言',
  `country_num` int(11) DEFAULT '156' COMMENT '国家语种默认156',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id` (`id`) USING BTREE,
  KEY `sid` (`sid`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7370 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='通用 菜单表';

-- ----------------------------
-- Records of lkt_menu
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_message
-- ----------------------------
DROP TABLE IF EXISTS `lkt_message`;
CREATE TABLE `lkt_message` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `SignName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` int(2) NOT NULL DEFAULT '0' COMMENT '类型 0:验证码 1:自定义',
  `type1` int(2) NOT NULL DEFAULT '0' COMMENT '类别 0:通用 1:申请通过 2:申请拒绝 3:订单提现 4:发货提现 5:收货提现',
  `TemplateCode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='短信模板列表';

-- ----------------------------
-- Records of lkt_message
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_message_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_message_config`;
CREATE TABLE `lkt_message_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `accessKeyId` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `accessKeySecret` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `SignName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='短信配置';

-- ----------------------------
-- Records of lkt_message_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_message_list
-- ----------------------------
DROP TABLE IF EXISTS `lkt_message_list`;
CREATE TABLE `lkt_message_list` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `type` int(2) NOT NULL DEFAULT '0' COMMENT '类型 0:验证码 1:短信通知',
  `type1` int(2) NOT NULL DEFAULT '0' COMMENT '类别 0:通用 1:申请通过 2:申请拒绝 3:订单提现 4:发货提现 5:收货提现',
  `Template_id` int(11) NOT NULL DEFAULT '0' COMMENT '模板id',
  `content` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` int(2) NOT NULL DEFAULT '0' COMMENT '类型 0:商城 1:店铺',
  `admin_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='短信列表';

-- ----------------------------
-- Records of lkt_message_list
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_message_logging
-- ----------------------------
DROP TABLE IF EXISTS `lkt_message_logging`;
CREATE TABLE `lkt_message_logging` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺id',
  `type` tinyint(3) NOT NULL DEFAULT '1' COMMENT '消息类型 1.订单(待发货) 2.订单(售后) 3.订单(提醒发货) 4.订单(订单关闭) 5.订单(新订单) 6.订单(收货) 7.商品(审核) 8.商品(下架) 9.商品(补货) 10.商品(新商品上架) 11.商品(分类) 12.商品(品牌) 13.提现 14.违规下架 15.商品删除 16.保证金审核消息通知 17.店铺商品审核消息通知',
  `parameter` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_popup` tinyint(2) NOT NULL DEFAULT '0' COMMENT '是否弹窗 0.未弹 1.已弹',
  `read_or_not` tinyint(2) NOT NULL DEFAULT '0' COMMENT '是否已读 0.未读 1.已读',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `to_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `supplier_id` int(11) NOT NULL DEFAULT '0' COMMENT '供应商id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `store_id_idx` (`store_id`) USING BTREE,
  KEY `mch_id_idx` (`mch_id`) USING BTREE,
  KEY `is_popup_idx` (`is_popup`) USING BTREE,
  KEY `read_or_not_idx` (`read_or_not`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4015 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺消息记录表';

-- ----------------------------
-- Records of lkt_message_logging
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_notice
-- ----------------------------
DROP TABLE IF EXISTS `lkt_notice`;
CREATE TABLE `lkt_notice` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '配置id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `pay_success` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `order_delivery` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `delivery` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `refund_res` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='模板消息表';

-- ----------------------------
-- Records of lkt_notice
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_online_message
-- ----------------------------
DROP TABLE IF EXISTS `lkt_online_message`;
CREATE TABLE `lkt_online_message` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `send_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `receive_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_mch_send` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否店铺发送 0否 1 是 店铺发送 id 为店铺id',
  `add_date` datetime NOT NULL COMMENT '添加时间',
  `is_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已读  0 否 1 是',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=96 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='客服聊天记录';

-- ----------------------------
-- Records of lkt_online_message
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_order
-- ----------------------------
DROP TABLE IF EXISTS `lkt_order`;
CREATE TABLE `lkt_order` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `num` int(11) DEFAULT NULL COMMENT '数量',
  `old_total` decimal(12,2) DEFAULT NULL COMMENT '历史总价',
  `z_price` decimal(12,2) DEFAULT NULL COMMENT '总价',
  `sNo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sheng` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `shi` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `xian` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `address` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pay` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `pay_time` timestamp NULL DEFAULT NULL COMMENT '支付时间',
  `arrive_time` timestamp NULL DEFAULT NULL COMMENT '到货时间',
  `order_failure_time` int(11) NOT NULL DEFAULT '0' COMMENT '订单当前失效时间',
  `status` tinyint(4) DEFAULT '0' COMMENT '状态 0:未付款 1:未发货 2:待收货 5:已完成 7:订单关闭 8:待核销',
  `coupon_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subtraction_id` int(11) DEFAULT NULL COMMENT '满减活动ID',
  `consumer_money` int(11) DEFAULT '0' COMMENT '消费金',
  `coupon_activity_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `drawid` int(11) DEFAULT '0' COMMENT '活动ID',
  `otype` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ptcode` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pid` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ptstatus` smallint(6) DEFAULT NULL COMMENT '拼团状态:0,未付款 1,拼团中 2,拼团成功 3,拼团失败',
  `groupman` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `refundsNo` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `trade_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_anonymous` int(1) DEFAULT '0' COMMENT '是否匿名(0,否  1.是',
  `logistics_service` int(1) DEFAULT NULL COMMENT '物流服务',
  `overall_evaluation` int(1) DEFAULT NULL COMMENT '总体评价',
  `spz_price` decimal(10,2) DEFAULT NULL COMMENT '商品总价',
  `reduce_price` decimal(10,2) DEFAULT NULL COMMENT '查询出的满减金额',
  `coupon_price` decimal(10,2) DEFAULT NULL COMMENT '查询出的优惠券金额',
  `red_packet` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `allow` int(8) DEFAULT '0' COMMENT '积分',
  `parameter` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `source` tinyint(4) NOT NULL DEFAULT '1' COMMENT '来源 1.小程序 2.app 3.支付宝小程序 4.头条小程序 5.百度小程序 6.pc端 7.H5',
  `delivery_status` int(1) DEFAULT '0' COMMENT '提醒发货',
  `readd` int(2) NOT NULL DEFAULT '0' COMMENT '是否已读（0，未读  1 已读）',
  `remind` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '提醒\r\n\r\n发货时间间隔',
  `offset_balance` decimal(10,2) DEFAULT NULL COMMENT '抵扣余额',
  `mch_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `zhekou` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '分销折扣',
  `grade_rate` decimal(10,2) DEFAULT NULL COMMENT '会员等级折扣',
  `score_deduction` int(11) NOT NULL DEFAULT '0' COMMENT '积分支付抵扣',
  `grade_score` int(11) DEFAULT NULL COMMENT '会员购物积分',
  `grade_fan` decimal(12,2) DEFAULT NULL COMMENT '会员返现金额',
  `p_sNo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bargain_id` int(11) DEFAULT NULL COMMENT '砍价活动id',
  `comm_discount` decimal(10,2) NOT NULL COMMENT '分销折扣',
  `real_sno` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `orderId` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `baiduId` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `self_lifting` tinyint(4) DEFAULT '0' COMMENT '自提 0.配送 1.自提 2.商家自配 3.虚拟订单需要线下核销 4.虚拟订单无需线下核销',
  `extraction_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `extraction_code_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `VerifiedBy_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '核销人类型 1.店主核销 2.门店核销',
  `VerifiedBy` int(11) DEFAULT '0' COMMENT '核销人ID',
  `is_put` tinyint(4) DEFAULT '0' COMMENT '是否发放佣金 0.否 1.是',
  `old_freight` decimal(12,2) DEFAULT NULL COMMENT '历史总运费',
  `z_freight` decimal(12,2) DEFAULT NULL COMMENT '总运费',
  `manual_offer` decimal(12,2) DEFAULT NULL COMMENT '代客下单手动优惠金额',
  `preferential_amount` decimal(12,2) DEFAULT NULL COMMENT '优惠金额',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.系统回收 2用户回收 3店铺回收',
  `single_store` int(11) NOT NULL DEFAULT '0' COMMENT '下单门店',
  `pick_up_store` tinyint(4) NOT NULL DEFAULT '0' COMMENT '取货门店',
  `store_write_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `platform_activities_id` int(11) DEFAULT NULL COMMENT '平台活动管理ID',
  `commission_type` tinyint(1) DEFAULT '0' COMMENT '分销订单结算标识0未结算1已结算',
  `settlement_status` tinyint(1) DEFAULT '0' COMMENT '结算状态',
  `operation_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '下单类型1用户下单2店铺下单3平台下单',
  `is_lssued` int(2) DEFAULT '0' COMMENT '店铺是否操作代发 0.否 1.是',
  `supplier_id` int(11) DEFAULT '0' COMMENT '供应商id',
  `user_recycle` tinyint(4) DEFAULT '1' COMMENT '用户删除 1.显示 2.删除',
  `mch_recycle` tinyint(4) DEFAULT '1' COMMENT '商户删除 1.显示 2.删除',
  `store_recycle` tinyint(4) DEFAULT '1' COMMENT '商城删除 1.显示 2.删除',
  `transaction_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `wx_order_status` int(11) DEFAULT NULL COMMENT '微信小程序订单状态枚举：(1) 待发货；(2) 已发货；(3) 确认收货；(4) 交易完成；(5) 已退款。',
  `dividend_status` tinyint(4) DEFAULT '0' COMMENT '分账状态 0.不分账 1.分账',
  `cancel_method` tinyint(4) DEFAULT '0' COMMENT '订单取消方式 0 定时任务取消订单  1 手动点击取消订单',
  `paypal_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '贝宝支付订单id',
  `currency_symbol` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付时货币符号',
  `exchange_rate` decimal(12,2) DEFAULT NULL COMMENT '支付时货币汇率',
  `currency_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付时货币编码',
  `capture_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '贝宝付款生成的ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `sNo` (`sNo`(191)) USING BTREE,
  KEY `subtraction_id` (`subtraction_id`) USING BTREE,
  KEY `store_id_2` (`store_id`) USING BTREE,
  KEY `user_id_2` (`user_id`) USING BTREE,
  KEY `sNo_2` (`sNo`(191)) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `mch_id` (`mch_id`(191)) USING BTREE,
  KEY `otype` (`otype`) USING BTREE,
  KEY `recycle` (`recycle`) USING BTREE,
  KEY `add_time` (`add_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1513 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单列表';

-- ----------------------------
-- Records of lkt_order
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_order_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_order_config`;
CREATE TABLE `lkt_order_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `days` int(11) DEFAULT NULL COMMENT '承若天数',
  `content` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `back` int(11) DEFAULT '2' COMMENT '退货时间',
  `order_failure` int(11) DEFAULT NULL COMMENT '订单失效',
  `order_after` int(3) NOT NULL DEFAULT '7' COMMENT '订单售后时间',
  `company` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `order_overdue` int(11) DEFAULT '2' COMMENT '订单过期删除时间',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `modify_date` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `auto_the_goods` int(11) DEFAULT '7' COMMENT '自动收货时间',
  `order_ship` int(11) NOT NULL DEFAULT '0' COMMENT '发货时限',
  `remind` int(11) DEFAULT '1' COMMENT '提醒限制',
  `accesscode` char(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `checkword` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `custid` char(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `package_settings` tinyint(4) DEFAULT '0' COMMENT '包邮设置 0.未开启 1.开启',
  `same_piece` int(11) DEFAULT '0' COMMENT '同件',
  `same_order` int(11) DEFAULT '0' COMMENT '同单',
  `auto_good_comment_day` smallint(5) NOT NULL DEFAULT '0' COMMENT '自动评价设置几后自动好评',
  `auto_comment_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `leader_rate` decimal(12,2) DEFAULT NULL COMMENT '社群领袖加盟套餐分成比例',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单设置';

-- ----------------------------
-- Records of lkt_order_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_order_data
-- ----------------------------
DROP TABLE IF EXISTS `lkt_order_data`;
CREATE TABLE `lkt_order_data` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `trade_no` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `order_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `data` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `addtime` datetime NOT NULL COMMENT '创建时间',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '支付状态 0未支付 1已支付',
  `pay_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `source` int(11) NOT NULL DEFAULT '1' COMMENT '来源',
  `currency_symbol` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付时货币符号',
  `exchange_rate` decimal(12,2) DEFAULT NULL COMMENT '支付时货币汇率',
  `currency_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付时货币编码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=187 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单临时信息表';

-- ----------------------------
-- Records of lkt_order_data
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_order_details
-- ----------------------------
DROP TABLE IF EXISTS `lkt_order_details`;
CREATE TABLE `lkt_order_details` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) DEFAULT '0' COMMENT '商城id',
  `user_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `p_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品id(插件则是插件商品id)',
  `p_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `p_price` decimal(12,2) DEFAULT NULL COMMENT '产品价格',
  `num` int(11) DEFAULT NULL COMMENT '数量',
  `actual_total` decimal(12,2) DEFAULT NULL COMMENT '实际支付金额',
  `score_deduction` int(11) NOT NULL DEFAULT '0' COMMENT '积分支付抵扣',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `r_sNo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `deliver_time` timestamp NULL DEFAULT NULL COMMENT '发货时间',
  `arrive_time` timestamp NULL DEFAULT NULL COMMENT '到货时间',
  `r_status` tinyint(4) DEFAULT '0' COMMENT '状态 0:未付款 1:未发货 2:待收货 5:已完成  7:订单关闭 8:待核销',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `reason` char(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `re_type` tinyint(4) DEFAULT '0' COMMENT '退款类型 1:退货退款  2:退款 3:售后',
  `re_apply_money` float(12,2) DEFAULT NULL COMMENT '用户申请退款金额',
  `re_money` float(12,2) DEFAULT NULL COMMENT '退款金额',
  `real_money` decimal(12,2) DEFAULT NULL COMMENT '实际退款金额',
  `re_time` datetime DEFAULT NULL COMMENT '申请退款时间',
  `re_photo` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `r_content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `r_type` tinyint(4) DEFAULT '100' COMMENT '类型 100:不在退货退款状态0:审核中 1:同意并让用户寄回 2:拒绝(退货退款) 3:用户已快递 4:收到寄回商品,同意并退款 5：拒绝并退回商品 8:拒绝(退款) 9:同意并退款 10:拒绝(售后)11:同意并且寄回商品 12售后结束',
  `express_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `courier_num` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `express_type` tinyint(4) DEFAULT '1' COMMENT '发货类型 1.手动发货 2.自动发货',
  `freight` decimal(12,2) DEFAULT NULL COMMENT '运费',
  `size` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sid` char(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `invoice` tinyint(4) DEFAULT '0' COMMENT '发货单打印 0.否 1.是',
  `express` tinyint(4) DEFAULT '0' COMMENT '快递单打印 0.否 1.是',
  `exchange_num` int(11) DEFAULT '0' COMMENT '换货次数',
  `coupon_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `manual_offer` decimal(12,2) DEFAULT NULL COMMENT '代课下单手动优惠金额',
  `after_discount` decimal(12,2) DEFAULT NULL COMMENT '优惠后的金额',
  `mch_id` int(11) DEFAULT NULL COMMENT '店铺ID',
  `settlement_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '订单结算标识 0未结算 1已结算',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.回收',
  `supplier_settlement` decimal(12,2) DEFAULT NULL COMMENT '总供货价',
  `supplier_id` int(11) DEFAULT '0' COMMENT '供应商id',
  `is_addp` tinyint(1) DEFAULT '0' COMMENT '是否加购商品',
  `user_recycle` tinyint(4) DEFAULT '1' COMMENT '用户删除 1.显示 2.删除',
  `mch_recycle` tinyint(4) DEFAULT '1' COMMENT '商户删除 1.显示 2.删除',
  `store_recycle` tinyint(4) DEFAULT '1' COMMENT '商城删除 1.显示 2.删除',
  `deliver_num` int(11) DEFAULT '0' COMMENT '发货数量',
  `third_party_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `third_party_json` longtext CHARACTER SET utf8 COLLATE utf8_general_ci COMMENT '第三方订单信息',
  `living_room_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `anchor_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `commission` decimal(12,2) DEFAULT NULL COMMENT '佣金',
  `write_off_num` int(10) DEFAULT NULL COMMENT '虚拟商品待核销次数',
  `after_write_off_num` int(10) DEFAULT NULL COMMENT '虚拟商品已核销次数',
  `mch_store_write_id` int(10) DEFAULT NULL COMMENT '预约门店id',
  `write_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `write_time_id` int(10) DEFAULT NULL COMMENT '预约时段id',
  `platform_coupon_price` decimal(12,2) DEFAULT NULL COMMENT '平台优惠券优惠金额',
  `store_coupon_price` decimal(12,2) DEFAULT NULL COMMENT '店铺优惠券优惠金额',
  `store_self_delivery` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `r_sNo` (`r_sNo`(191)) USING BTREE,
  KEY `sid` (`sid`) USING BTREE,
  KEY `store_id_2` (`store_id`) USING BTREE,
  KEY `mch_id` (`mch_id`) USING BTREE,
  KEY `recycle` (`recycle`) USING BTREE,
  KEY `p_id` (`p_id`) USING BTREE,
  KEY `r_status` (`r_status`) USING BTREE,
  KEY `re_type` (`re_type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1838 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单详情列表';

-- ----------------------------
-- Records of lkt_order_details
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_order_report
-- ----------------------------
DROP TABLE IF EXISTS `lkt_order_report`;
CREATE TABLE `lkt_order_report` (
  `type` tinyint(10) NOT NULL COMMENT '统计指标 5 用户报表 7 订单总数 6退付款总数',
  `num` bigint(10) DEFAULT '0' COMMENT '数量',
  `data` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `store_id` int(11) DEFAULT NULL COMMENT '商城id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单数据统计表';

-- ----------------------------
-- Records of lkt_order_report
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_payment
-- ----------------------------
DROP TABLE IF EXISTS `lkt_payment`;
CREATE TABLE `lkt_payment` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1:线上、2:线下',
  `class_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `description` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态 0启用 1禁用',
  `sort` smallint(5) NOT NULL DEFAULT '99' COMMENT '排序',
  `note` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `poundage` decimal(15,2) NOT NULL COMMENT '手续费',
  `poundage_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '手续费方式 1百分比 2固定值',
  `client_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1:PC端 2:移动端 3:通用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='支付方式表';

-- ----------------------------
-- Records of lkt_payment
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_payment_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_payment_config`;
CREATE TABLE `lkt_payment_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `pid` int(11) NOT NULL COMMENT '支付方式id',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否显示 0否 1是',
  `config_data` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `isdefaultpay` tinyint(1) DEFAULT '2' COMMENT '是否默认支付方式 1是2否',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=991 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='支付方式参数表';

-- ----------------------------
-- Records of lkt_payment_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_pc_mall_bottom
-- ----------------------------
DROP TABLE IF EXISTS `lkt_pc_mall_bottom`;
CREATE TABLE `lkt_pc_mall_bottom` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subheading` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序号',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `update_date` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='PC商城底部栏图片配置';

-- ----------------------------
-- Records of lkt_pc_mall_bottom
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_pc_mall_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_pc_mall_config`;
CREATE TABLE `lkt_pc_mall_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `type` int(11) DEFAULT NULL COMMENT '配置类型 1浏览器标签 2 登录页配置 3 首页配置',
  `value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `update_date` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='PC商城页面显示配置';

-- ----------------------------
-- Records of lkt_pc_mall_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_platform_activities
-- ----------------------------
DROP TABLE IF EXISTS `lkt_platform_activities`;
CREATE TABLE `lkt_platform_activities` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id自增',
  `store_id` int(11) NOT NULL COMMENT '商品id',
  `image` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(1) NOT NULL COMMENT '活动状态 （1未开始 2进行中 3结束）',
  `default_num` int(11) NOT NULL DEFAULT '0' COMMENT '默认数量（秒杀）',
  `buy_time` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `group_man` int(11) NOT NULL DEFAULT '0' COMMENT '拼团人数（拼团）',
  `group_can` int(4) NOT NULL DEFAULT '0' COMMENT '参团折扣（拼团）',
  `group_kai` int(4) NOT NULL DEFAULT '0' COMMENT '开团折扣（拼团）',
  `group_time` int(3) NOT NULL DEFAULT '0' COMMENT '拼团时间（拼团）',
  `group_kai_num` int(4) NOT NULL DEFAULT '0' COMMENT '开团数量限制（拼团）',
  `group_can_num` int(4) NOT NULL DEFAULT '0' COMMENT '参团数量限制（拼团）',
  `group_can_again` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否开启参团重复 （1开启 0不开启）（拼团）',
  `free_freight` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否免邮(1 是 0 否)',
  `starttime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '开始时间',
  `endtime` timestamp NULL DEFAULT NULL COMMENT '结束时间',
  `join_starttime` timestamp NULL DEFAULT NULL COMMENT '报名开始时间',
  `join_endtime` timestamp NULL DEFAULT NULL COMMENT '报名结束时间',
  `isdelete` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否删除(1 是 0 否)',
  `addtime` timestamp NULL DEFAULT NULL COMMENT '添加日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='平台活动表';

-- ----------------------------
-- Records of lkt_platform_activities
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_platform_activities_del
-- ----------------------------
DROP TABLE IF EXISTS `lkt_platform_activities_del`;
CREATE TABLE `lkt_platform_activities_del` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `platform_activities_id` int(11) DEFAULT NULL COMMENT '平台活动ID',
  `mch_id` int(11) DEFAULT NULL COMMENT '商户ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商户删除平台管理活动表';

-- ----------------------------
-- Records of lkt_platform_activities_del
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_plugins
-- ----------------------------
DROP TABLE IF EXISTS `lkt_plugins`;
CREATE TABLE `lkt_plugins` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `store_id` int(11) DEFAULT '0' COMMENT '商城ID',
  `plugin_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `plugin_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `plugin_img` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `optime` datetime DEFAULT NULL COMMENT '安装时间',
  `status` int(1) DEFAULT '1' COMMENT '插件状态 0.关闭 1.开启',
  `flag` int(1) NOT NULL DEFAULT '0' COMMENT '是否有权限 0.有 1.没有',
  `opuser` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `jump_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `menu_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_mch_plugin` int(11) NOT NULL DEFAULT '1' COMMENT '插件是否支持pc店铺 1支持 2不支持',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1238 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商城插件信息表';

-- ----------------------------
-- Records of lkt_plugins
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_pre_sell_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_pre_sell_config`;
CREATE TABLE `lkt_pre_sell_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键自增',
  `store_id` int(11) NOT NULL COMMENT '店铺id',
  `is_open` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否开启 1 是 0 否',
  `deposit_desc` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `balance_desc` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `order_failure` int(11) NOT NULL DEFAULT '0' COMMENT '订单失效 (单位 秒)',
  `order_after` int(11) NOT NULL DEFAULT '604800' COMMENT '订单售后时间 (单位秒)',
  `auto_the_goods` int(11) NOT NULL DEFAULT '7' COMMENT '自动收货时间（单位秒）',
  `deliver_remind` int(11) NOT NULL DEFAULT '3600' COMMENT '提醒发货限制 间隔(单位秒)',
  `package_settings` tinyint(4) NOT NULL DEFAULT '0' COMMENT '多件包邮设置 0.未开启 1.开启',
  `same_piece` int(11) NOT NULL DEFAULT '0' COMMENT '同件',
  `same_order` int(11) NOT NULL DEFAULT '0' COMMENT '同单',
  `auto_good_comment_day` int(5) NOT NULL DEFAULT '0' COMMENT '自动评价设置几后自动好评',
  `auto_good_comment_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='预售配置信息';

-- ----------------------------
-- Records of lkt_pre_sell_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_pre_sell_goods
-- ----------------------------
DROP TABLE IF EXISTS `lkt_pre_sell_goods`;
CREATE TABLE `lkt_pre_sell_goods` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '唯一标识',
  `product_id` int(20) NOT NULL COMMENT '商品id',
  `product_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sell_type` int(10) NOT NULL DEFAULT '1' COMMENT '预售类型   1.订金模式   2.订货模式',
  `deposit` decimal(20,2) DEFAULT NULL COMMENT '订金金额',
  `pay_type` int(10) DEFAULT NULL COMMENT '订金支付类型',
  `deposit_start_time` datetime DEFAULT NULL COMMENT '订金支付开始时间',
  `deposit_end_time` datetime DEFAULT NULL COMMENT '订金支付结束时间',
  `balance_pay_time` datetime DEFAULT NULL COMMENT '尾款支付日期',
  `sell_num` int(20) DEFAULT NULL COMMENT '预售数量',
  `surplus_num` int(20) DEFAULT NULL COMMENT '剩余数量',
  `end_day` int(20) DEFAULT '1' COMMENT '截止天数',
  `deadline` datetime DEFAULT NULL COMMENT '截止时间',
  `delivery_time` int(10) NOT NULL COMMENT '发货时间(天)',
  `is_on_shelf` int(10) NOT NULL DEFAULT '0' COMMENT '是否上架过',
  `is_display` int(10) NOT NULL DEFAULT '1' COMMENT '是否显示 0.否  1.是',
  `is_delete` int(10) NOT NULL DEFAULT '0' COMMENT '是否删除  0.否  1.是',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='预售商品表';

-- ----------------------------
-- Records of lkt_pre_sell_goods
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_pre_sell_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_pre_sell_record`;
CREATE TABLE `lkt_pre_sell_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id自增',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `product_id` int(11) NOT NULL COMMENT '商品id',
  `attr_id` int(11) NOT NULL COMMENT '规格id',
  `price` decimal(11,2) NOT NULL COMMENT '当前付款金额',
  `deposit` decimal(11,2) DEFAULT NULL COMMENT '应付订金金额',
  `balance` decimal(11,2) DEFAULT NULL COMMENT '应付尾款金额',
  `num` int(11) NOT NULL COMMENT '数量',
  `sNo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_deposit` int(10) DEFAULT NULL COMMENT '是否支付订金  0.否  1.是',
  `is_balance` int(10) DEFAULT NULL COMMENT '是否支付尾款  0.否  1.是',
  `is_refund` int(10) DEFAULT '0' COMMENT '是否退款成功  0.否  1.是',
  `is_delete` int(10) NOT NULL DEFAULT '0' COMMENT '是否删除 1是 0否',
  `add_time` datetime DEFAULT NULL COMMENT '订金支付时间',
  `pay_balance_time` datetime DEFAULT NULL COMMENT '尾款支付时间',
  `order_info` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `order_details_info` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='预售记录表';

-- ----------------------------
-- Records of lkt_pre_sell_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_print_setup
-- ----------------------------
DROP TABLE IF EXISTS `lkt_print_setup`;
CREATE TABLE `lkt_print_setup` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id自增',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `supplier_id` int(11) DEFAULT NULL,
  `mch_id` int(11) DEFAULT NULL COMMENT '店铺id',
  `print_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `print_url` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sheng` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `shi` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `xian` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` datetime DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `mch_id` (`mch_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='订单打印配置';

-- ----------------------------
-- Records of lkt_print_setup
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_pro_label
-- ----------------------------
DROP TABLE IF EXISTS `lkt_pro_label`;
CREATE TABLE `lkt_pro_label` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `color` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `lang_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'zh_CN' COMMENT '语种编码默认中文简体',
  `country_num` int(11) DEFAULT '156' COMMENT '国家语种默认156',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品标签表';

-- ----------------------------
-- Records of lkt_pro_label
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_product_class
-- ----------------------------
DROP TABLE IF EXISTS `lkt_product_class`;
CREATE TABLE `lkt_product_class` (
  `cid` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '分类id',
  `sid` int(11) NOT NULL COMMENT '上级id',
  `pname` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `english_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `img` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `level` int(11) NOT NULL COMMENT '级别',
  `sort` int(11) DEFAULT '100' COMMENT '排序',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `recycle` tinyint(4) DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  `is_display` tinyint(3) DEFAULT '0' COMMENT '是否显示 0.不显示 1.显示',
  `is_default` int(2) DEFAULT '0' COMMENT '是否默认分类',
  `mch_id` int(11) NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `supplier_id` int(11) NOT NULL DEFAULT '0' COMMENT '供应商ID',
  `examine` tinyint(4) DEFAULT '0' COMMENT '审核状态 0.待审核 1.审核通过 2.不通过',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '拒绝原因',
  `lang_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'zh_CN' COMMENT '语种编码默认中文简体',
  `country_num` int(11) DEFAULT '156' COMMENT '国家语种默认156',
  `notset` int(11) DEFAULT '0' COMMENT '未设置 默认值为0  为1的时候表示是未设置 ',
  PRIMARY KEY (`cid`) USING BTREE,
  KEY `sid` (`sid`) USING BTREE,
  KEY `pname` (`pname`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `recycle` (`recycle`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=131 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品分类';

-- ----------------------------
-- Records of lkt_product_class
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_product_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_product_config`;
CREATE TABLE `lkt_product_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `config` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `is_open` tinyint(4) DEFAULT '0' COMMENT '是否显示下架商品 0.不显示  1.显示',
  `is_display_sell_put` tinyint(4) DEFAULT '0' COMMENT '是否显示已售罄商品 0.不显示  1.显示',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='产品配置表';

-- ----------------------------
-- Records of lkt_product_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_product_img
-- ----------------------------
DROP TABLE IF EXISTS `lkt_product_img`;
CREATE TABLE `lkt_product_img` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '图片id',
  `product_url` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `product_id` int(11) NOT NULL COMMENT '所属产品id',
  `seller_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `product_id` (`product_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='图片表';

-- ----------------------------
-- Records of lkt_product_img
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_product_list
-- ----------------------------
DROP TABLE IF EXISTS `lkt_product_list`;
CREATE TABLE `lkt_product_list` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '商品id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `product_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `commodity_type` tinyint(2) DEFAULT '0' COMMENT '商品类型 0.实物商品 1.虚拟商品 2.直播商品',
  `product_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subtitle` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `label` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `scan` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `product_class` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `imgurl` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `richList` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `mch_sort` int(11) DEFAULT '1' COMMENT '店铺排序值',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `upper_shelf_time` timestamp NULL DEFAULT NULL COMMENT '上架时间',
  `volume` int(12) NOT NULL DEFAULT '0' COMMENT '销量',
  `initial` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `s_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `num` int(11) NOT NULL DEFAULT '0' COMMENT '数量',
  `min_inventory` int(11) NOT NULL DEFAULT '10' COMMENT '库存预警',
  `status` tinyint(3) NOT NULL DEFAULT '1' COMMENT '状态 1:待上架 2:上架 3:下架 4.违规下架 5.断供',
  `brand_id` int(11) NOT NULL DEFAULT '0' COMMENT '品牌ID',
  `is_distribution` int(2) NOT NULL DEFAULT '0' COMMENT '是否为分销商品',
  `is_default_ratio` int(2) NOT NULL DEFAULT '0' COMMENT '是否默认比例',
  `keyword` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `weight` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `weight_unit` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `distributor_id` int(5) DEFAULT '0' COMMENT '分销等级id 购买就升级',
  `freight` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_zhekou` int(2) DEFAULT '0' COMMENT '是否开启会员',
  `separate_distribution` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.回收',
  `gongyingshang` int(11) DEFAULT '0' COMMENT '供应商ID',
  `is_hexiao` tinyint(4) DEFAULT '0' COMMENT '是否支持线下核销:0--不支持　1--支持',
  `hxaddress` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `active` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mch_id` int(10) unsigned DEFAULT '0' COMMENT '商户ID',
  `mch_status` tinyint(2) NOT NULL DEFAULT '1' COMMENT '审核状态：1.待审核，2.审核通过，3.审核不通过，4.暂不审核',
  `refuse_reasons` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `search_num` int(11) NOT NULL DEFAULT '0' COMMENT '搜索次数',
  `show_adr` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `publisher` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_zixuan` tinyint(4) DEFAULT '1' COMMENT '是否自选 0.自选 1.不是自选',
  `commodity_str` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `source` tinyint(4) DEFAULT '2' COMMENT '来源 1.自选 2.上传',
  `comment_num` int(11) DEFAULT '0' COMMENT '评论数',
  `cover_map` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `class_sort` int(11) DEFAULT '0' COMMENT '分类排序',
  `display_position_sort` int(11) DEFAULT '0' COMMENT '显示位置排序',
  `is_presell` int(11) DEFAULT '0' COMMENT '是否为预售商品 0.否  1.是',
  `supplier_superior` int(11) DEFAULT '0' COMMENT '供应商商品上级id',
  `lower_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `outage_time` datetime DEFAULT NULL COMMENT '断供时间',
  `pro_param` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `pro_introduce` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `examine_time` datetime DEFAULT NULL COMMENT '审核时间',
  `violation_time` datetime DEFAULT NULL COMMENT '违规下架时间',
  `receiving_form` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `zixuan_id` int(11) DEFAULT '0' COMMENT '自选id',
  `video` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pro_video` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `real_volume` int(11) DEFAULT '0' COMMENT '真实销量',
  `lower_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `write_off_settings` int(4) DEFAULT NULL COMMENT '核销设置 1.线下核销 2.无需核销',
  `write_off_mch_ids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_appointment` int(4) DEFAULT '1' COMMENT '预约时间设置 1.无需预约下单 2.需要预约下单',
  `country_num` int(11) NOT NULL DEFAULT '156' COMMENT '国家代码 默认中国编码：156',
  `lang_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'zh_CN' COMMENT '国际化语言 默认：中文简体 zh_CN',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `product_title` (`product_title`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `recycle` (`recycle`) USING BTREE,
  KEY `brand_id` (`brand_id`) USING BTREE,
  KEY `mch_id` (`mch_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=537 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品表';

-- ----------------------------
-- Records of lkt_product_list
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_product_number
-- ----------------------------
DROP TABLE IF EXISTS `lkt_product_number`;
CREATE TABLE `lkt_product_number` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `mch_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `operation` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `product_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(3) NOT NULL DEFAULT '1' COMMENT '状态：1.使用 2.撤销',
  `addtime` timestamp NULL DEFAULT NULL COMMENT '时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6770 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品编号表';

-- ----------------------------
-- Records of lkt_product_number
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_promise_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_promise_record`;
CREATE TABLE `lkt_promise_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `store_id` int(11) NOT NULL COMMENT '商城ID',
  `mch_id` int(11) NOT NULL COMMENT '店铺ID',
  `money` decimal(10,2) NOT NULL COMMENT '保证金金额',
  `type` int(11) NOT NULL COMMENT '记录类型 1:缴纳，2:退还',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `promise_sh_id` varbinary(255) DEFAULT NULL COMMENT '保证金审核id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='保证金审核记录表';

-- ----------------------------
-- Records of lkt_promise_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_promise_sh
-- ----------------------------
DROP TABLE IF EXISTS `lkt_promise_sh`;
CREATE TABLE `lkt_promise_sh` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  `promise_amt` decimal(10,2) NOT NULL COMMENT '保证金金额',
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '保证金审核状态 1=通过 2=拒绝 3=审核中',
  `pay_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_pass` int(255) NOT NULL DEFAULT '0' COMMENT '是否通过 1=通过 2=不通过 3=审核中',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `refused_why` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `refused_date` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='保证金审核';

-- ----------------------------
-- Records of lkt_promise_sh
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_record`;
CREATE TABLE `lkt_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `money` decimal(12,2) DEFAULT NULL COMMENT '操作金额',
  `oldmoney` decimal(12,2) DEFAULT NULL COMMENT '原有金额',
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `event` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '类型 0:登录/退出 1:充值 2:申请提现 3:分享 4:余额消费 5:退款 6:红包提现 7:佣金 8:管理佣金 9:待定 10:消费金 11:系统扣款   12:给好友转余额 13:转入余额 14:系统充值 15:系统充积分 16:系统充消费金 17:系统扣积分 18:系统扣消费金 19:消费金解封 20:抽奖中奖 21:  提现成功 22:提现失败 23.取消订单  24分享获取红包 26 交竞拍押金 27 退竞拍押金 28 售后（仅退款） 29 售后（退货退款）30 会员返现  42.主播佣金',
  `is_mch` int(2) DEFAULT '0' COMMENT '是否是店铺提现 0.不是店铺提现 1.是店铺提现',
  `main_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `details_id` int(11) NOT NULL DEFAULT '0' COMMENT '记录详情id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `lkt_record_user_id` (`user_id`(191)) USING BTREE,
  KEY `lkt_record_type` (`type`) USING BTREE,
  KEY `lkt_record_store_id` (`store_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5200 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='操作记录表';

-- ----------------------------
-- Records of lkt_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_record_details
-- ----------------------------
DROP TABLE IF EXISTS `lkt_record_details`;
CREATE TABLE `lkt_record_details` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `money` decimal(12,2) NOT NULL COMMENT '操作金额',
  `user_money` decimal(12,2) NOT NULL COMMENT '账户余额',
  `type` tinyint(4) NOT NULL COMMENT '账单类型 1 余额充值(用户)  2余额充值(平台)  3活动佣金  4订单退款 5店铺保证金提取 6 平台扣款  7 订单支付  8 参与活动  9充值会员  10 店铺保证金支付  11余额提现  12活动退款',
  `money_type` int(4) NOT NULL COMMENT '1 收入类型  2支出类型',
  `money_type_name` tinyint(4) DEFAULT NULL COMMENT '收入/支出 名称   1.用户充值 2.平台充值 3.拼团活动开团佣金 4.普通订单 5.竞拍活动 6.店铺保证金 7.余额扣款 8.预售定金缴纳  9.会员开通 10.普通订单(代客下单) 11.拼团订单 12.竟拍订单 13.预售订单 14.分稍订单 15.秒杀订单 16.积分兑换订单 17.限时折扣订单 18.竞拍保证金缴纳 19.虚拟订单',
  `record_time` datetime DEFAULT NULL COMMENT '到账时间/提现时间/支出时间',
  `record_notes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `type_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '充值方式/退款类型/活动类型',
  `s_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '订单号',
  `title_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商品名字/活动名称',
  `activity_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '活动编号',
  `mch_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '店铺名称',
  `withdrawal_fees` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '提现手续费',
  `withdrawal_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '提现方式',
  `add_time` datetime DEFAULT NULL COMMENT '添加时间',
  `currency_symbol` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付时货币符号',
  `exchange_rate` decimal(12,2) DEFAULT NULL COMMENT '支付时货币汇率',
  `currency_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付时货币编码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1576 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='操作记录详情';

-- ----------------------------
-- Records of lkt_record_details
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_reply_comments
-- ----------------------------
DROP TABLE IF EXISTS `lkt_reply_comments`;
CREATE TABLE `lkt_reply_comments` (
  `id` int(15) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `cid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `uid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_time` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `to_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sid` int(11) DEFAULT '0' COMMENT '回复的上级id',
  `type` int(11) DEFAULT '0' COMMENT '是否是商家回复 0=用户评论 1=商家评论',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='回复评论表';

-- ----------------------------
-- Records of lkt_reply_comments
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_return_goods
-- ----------------------------
DROP TABLE IF EXISTS `lkt_return_goods`;
CREATE TABLE `lkt_return_goods` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `tel` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `express` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `express_num` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `uid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `oid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_data` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '填写时间',
  `user_id` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `re_id` int(11) NOT NULL DEFAULT '0' COMMENT '售后订单ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户退货表';

-- ----------------------------
-- Records of lkt_return_goods
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_return_order
-- ----------------------------
DROP TABLE IF EXISTS `lkt_return_order`;
CREATE TABLE `lkt_return_order` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `store_id` int(11) NOT NULL COMMENT '商城ID',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sNo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `p_id` int(11) NOT NULL COMMENT '订单详情ID',
  `re_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '退款类型 1:退货退款  2:退款 3:换货',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `re_apply_money` float(12,2) NOT NULL DEFAULT '0.00' COMMENT '用户申请退款金额',
  `re_money` float(12,2) NOT NULL DEFAULT '0.00' COMMENT '退款金额',
  `real_money` float(12,2) NOT NULL DEFAULT '0.00' COMMENT '实际退款金额',
  `re_time` datetime NOT NULL COMMENT '申请售后时间',
  `re_photo` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `r_content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `r_type` tinyint(1) NOT NULL DEFAULT '100' COMMENT '类型 100:不在退货退款状态0:审核中 1:同意并让用户寄回 2:拒绝(退货退款) 3:用户已快递 4:收到寄回商品,同意并退款 5:拒绝并退回商品 8:拒绝(退款) 9:同意并退款 10:拒绝(售后) 11:同意并且寄回商品 12:售后结束 13:人工售後完成 15:极速退款 16 收到回寄商品,确定不影响二次销售',
  `sid` int(11) NOT NULL COMMENT '商品属性id',
  `pid` int(11) NOT NULL COMMENT '商品ID',
  `re_id` int(11) NOT NULL DEFAULT '0' COMMENT '售后ID',
  `is_agree` tinyint(1) DEFAULT '0' COMMENT '店铺是否同意 0.否 1.是',
  `r_write_off_num` int(10) DEFAULT NULL COMMENT '虚拟商品退款核销次数',
  `audit_status` tinyint(4) DEFAULT '0' COMMENT '审核状态 0.正常 1.极速退款等待回调 2.不是极速退款等待回调',
  `refund_Id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'paypal生成的退款ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=638 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='售后订单表';

-- ----------------------------
-- Records of lkt_return_order
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_return_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_return_record`;
CREATE TABLE `lkt_return_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id自增',
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `store_id` int(11) NOT NULL COMMENT '店铺id',
  `re_type` tinyint(1) NOT NULL COMMENT '售后类型：1仅退款 2退货退款 3换货',
  `r_type` int(3) NOT NULL COMMENT '售后状态',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `sNo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `money` decimal(10,2) NOT NULL COMMENT '售后金额',
  `real_money` decimal(10,2) DEFAULT NULL COMMENT '实际退款金额',
  `re_photo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `product_id` int(5) NOT NULL COMMENT '商品id',
  `attr_id` int(11) NOT NULL COMMENT '属性id',
  `express_id` int(11) DEFAULT NULL COMMENT '快递公司id',
  `courier_num` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `re_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '添加日期',
  `explain` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `p_id` int(11) NOT NULL COMMENT '上级详情订单id',
  `is_it_manual` tinyint(4) NOT NULL DEFAULT '1' COMMENT '是否是人工 0.系统自动 1.人工',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=915 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='售后记录表';

-- ----------------------------
-- Records of lkt_return_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_role
-- ----------------------------
DROP TABLE IF EXISTS `lkt_role`;
CREATE TABLE `lkt_role` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `permission` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '状态 0:角色 1:客户端',
  `admin_id` int(11) NOT NULL DEFAULT '0' COMMENT '管理员id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `role_describe` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `id` (`id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `admin_id` (`admin_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='角色表';

-- ----------------------------
-- Records of lkt_role
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_role_menu
-- ----------------------------
DROP TABLE IF EXISTS `lkt_role_menu`;
CREATE TABLE `lkt_role_menu` (
  `role_id` int(11) NOT NULL DEFAULT '0' COMMENT '角色ID',
  `menu_id` int(11) NOT NULL DEFAULT '0' COMMENT '菜单ID',
  `is_display` tinyint(4) DEFAULT '0' COMMENT '是否显示 0.不显示 1.显示',
  `guide_sort` int(11) DEFAULT '0' COMMENT '导览排序',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  KEY `index_menu_id` (`menu_id`) USING BTREE,
  KEY `role_id` (`role_id`) USING BTREE,
  KEY `is_display` (`is_display`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='权限菜单';

-- ----------------------------
-- Records of lkt_role_menu
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_score_over
-- ----------------------------
DROP TABLE IF EXISTS `lkt_score_over`;
CREATE TABLE `lkt_score_over` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `old_score` bigint(24) NOT NULL DEFAULT '0' COMMENT '原积分',
  `now_score` bigint(24) DEFAULT '0' COMMENT '现积分',
  `last_pay` int(11) DEFAULT '0' COMMENT '已计算花费积分',
  `count_time` timestamp NULL DEFAULT NULL COMMENT '上次过期时间',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '计算时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='积分过期记录表';

-- ----------------------------
-- Records of lkt_score_over
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_seconds_activity
-- ----------------------------
DROP TABLE IF EXISTS `lkt_seconds_activity`;
CREATE TABLE `lkt_seconds_activity` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id自增',
  `store_id` int(11) NOT NULL COMMENT '店铺id',
  `goodsId` int(11) NOT NULL COMMENT '商品id',
  `label_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '标签ID',
  `attr_id` int(11) NOT NULL DEFAULT '0' COMMENT '规格ID',
  `seconds_price` decimal(11,2) NOT NULL COMMENT '秒杀价格',
  `price_type` int(11) NOT NULL DEFAULT '0' COMMENT '秒杀价格单位 0=百分比 1=固定值',
  `num` int(11) NOT NULL COMMENT '秒杀库存',
  `max_num` int(11) DEFAULT NULL COMMENT '最大数量',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` int(1) NOT NULL DEFAULT '1' COMMENT '活动状态 1 未开始 2 进行中 3结束',
  `type` tinyint(1) DEFAULT NULL COMMENT '活动类型',
  `starttime` datetime NOT NULL COMMENT '活动开始时间',
  `endtime` datetime NOT NULL COMMENT '活动结束时间',
  `isshow` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否显示 1 是 0 否',
  `is_delete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除 1 是 0 否',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime DEFAULT NULL COMMENT '修改时间',
  `isNotice` int(11) NOT NULL DEFAULT '0' COMMENT '是否通知 0=未通知 1=已通知',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=181 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of lkt_seconds_activity
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_seconds_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_seconds_config`;
CREATE TABLE `lkt_seconds_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键自增',
  `store_id` int(11) NOT NULL COMMENT '店铺id',
  `is_open` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否开启 1 是 0 否',
  `buy_num` int(11) NOT NULL COMMENT '秒杀商品默认限购数量',
  `imageurl` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_herald` int(11) NOT NULL DEFAULT '0' COMMENT '是否开启预告',
  `heraldTime` int(11) NOT NULL DEFAULT '0' COMMENT '预告时间 （单位:秒）',
  `remind` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pcAdImg` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `rule` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `order_failure` int(11) NOT NULL DEFAULT '0' COMMENT '订单失效 (单位 秒)',
  `order_after` int(3) NOT NULL DEFAULT '604800' COMMENT '订单售后时间 (单位秒)',
  `auto_the_goods` int(11) NOT NULL DEFAULT '7' COMMENT '自动收货时间',
  `deliver_remind` int(11) NOT NULL DEFAULT '3600' COMMENT '提醒发货限制 间隔(单位 秒)',
  `package_settings` tinyint(4) NOT NULL DEFAULT '0' COMMENT '多件包邮设置 0.未开启 1.开启',
  `same_piece` int(11) NOT NULL DEFAULT '0' COMMENT '同件',
  `same_order` int(11) NOT NULL DEFAULT '0' COMMENT '同单',
  `auto_good_comment_day` int(5) NOT NULL DEFAULT '0' COMMENT '自动评价设置几后自动好评',
  `auto_good_comment_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mch_id` int(11) NOT NULL COMMENT '店铺id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of lkt_seconds_config
