-- Table structure for lkt_seconds_day_delete
-- ----------------------------
DROP TABLE IF EXISTS `lkt_seconds_day_delete`;
CREATE TABLE `lkt_seconds_day_delete` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `activity_id` int(11) NOT NULL COMMENT '秒杀活动id',
  `day` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` datetime NOT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='秒杀活动单天数删除记录表';

