-- ----------------------------
DROP TABLE IF EXISTS `lkt_sensitive_words`;
CREATE TABLE `lkt_sensitive_words` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `store_id` int(11) DEFAULT NULL COMMENT '商城id',
  `word` text CHARACTER SET utf8 COLLATE utf8_general_ci COMMENT '敏感词',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `recycle` int(11) DEFAULT '0' COMMENT '逻辑删除标志',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='敏感词表';

