CREATE TABLE `lkt_session_id` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `session_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `type` tinyint(4) DEFAULT '0' COMMENT '类型 0.发送短信 1.商\n\n\r\n品 2.退货申请 3.评论 4.邮箱验证码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=153 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='session_id表';

