-- Table structure for lkt_setscore
-- ----------------------------
DROP TABLE IF EXISTS `lkt_setscore`;
CREATE TABLE `lkt_setscore` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `lever` smallint(6) DEFAULT NULL COMMENT '等级',
  `ordernum` int(11) DEFAULT NULL COMMENT '订单金额',
  `scorenum` int(11) DEFAULT NULL COMMENT '可抵用消费金额',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='积分抵用消费金额表';

-- ----------------------------
-- Records of lkt_setscore
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_sign_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_sign_config`;
CREATE TABLE `lkt_sign_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `is_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '签到插件是否启用 0：未启用 1：启用',
  `score_num` int(11) NOT NULL DEFAULT '0' COMMENT '签到次数',
  `starttime` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `endtime` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_remind` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否提醒 0：不提醒 1：提醒',
  `reset` int(11) NOT NULL DEFAULT '0' COMMENT '间隔时间',
  `imgurl` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `score` int(11) NOT NULL DEFAULT '0' COMMENT '领取积分',
  `continuity` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `detail` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `Instructions` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `modify_date` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `is_many_time` tinyint(4) DEFAULT '0' COMMENT '是否允许多次 0:不允许  1:允许',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='签到配置表';

-- ----------------------------
-- Records of lkt_sign_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_sign_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_sign_record`;
CREATE TABLE `lkt_sign_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sign_score` int(11) NOT NULL DEFAULT '0' COMMENT '签到积分',
  `total_score` int(11) NOT NULL DEFAULT '0' COMMENT '总积分',
  `record` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `score_invalid` datetime DEFAULT NULL COMMENT '积分过期时间  永不过期则为null',
  `sign_time` timestamp NULL DEFAULT NULL COMMENT '签到时间',
  `type` int(4) NOT NULL DEFAULT '0' COMMENT '类型: 0:签到 1:消费 2:首次关注得积分  4:转积分给好友 5:系统扣除 6:系统充值 7:抽奖 8:会员购物积分 9:分销升级奖励积分 10:积分过期 11.开通会员 12.会员生日特权 13.冻结积分 14.售后退回',
  `recovery` tinyint(2) DEFAULT '0' COMMENT '是否删除 0.未删除 1.\r\n删除',
  `sNo` char(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `frozen_time` datetime DEFAULT NULL COMMENT '冻结结束时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=827 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='签到记录（积分）';

-- ----------------------------
-- Records of lkt_sign_record
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_sku
-- ----------------------------
DROP TABLE IF EXISTS `lkt_sku`;
CREATE TABLE `lkt_sku` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `sid` int(11) NOT NULL DEFAULT '0' COMMENT '上级ID',
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否生效 0:不是 1:是',
  `type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '类型 1.属性名 2.属性值',
  `admin_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0:正常 1:回收',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `is_examine` int(11) NOT NULL DEFAULT '0' COMMENT '审核状态 0.未审核  1.已审核',
  `lang_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'zh_CN' COMMENT '语种编码',
  `country_num` int(11) NOT NULL DEFAULT '156' COMMENT '所属国家',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `sid` (`sid`) USING BTREE,
  KEY `name` (`name`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `recycle` (`recycle`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3284 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='属性表';

-- ----------------------------
-- Records of lkt_sku
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_stock
-- ----------------------------
DROP TABLE IF EXISTS `lkt_stock`;
CREATE TABLE `lkt_stock` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品id',
  `attribute_id` int(11) NOT NULL DEFAULT '0' COMMENT '属性id',
  `total_num` int(11) NOT NULL COMMENT '总库存',
  `flowing_num` int(11) NOT NULL DEFAULT '0' COMMENT '入库/出库',
  `type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '类型 0.入库 1.出库 2.预警',
  `user_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  `is_acceptance` tinyint(2) DEFAULT '0' COMMENT '是否受理 0.否 1.是',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `store_id` (`store_id`) USING BTREE,
  KEY `product_id` (`product_id`) USING BTREE,
  KEY `attribute_id` (`attribute_id`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3955 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='库存记录表';

-- ----------------------------
-- Records of lkt_stock
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_supplier
-- ----------------------------
DROP TABLE IF EXISTS `lkt_supplier`;
CREATE TABLE `lkt_supplier` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL COMMENT '商城id',
  `account_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `supplier_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `price` decimal(12,2) NOT NULL COMMENT '价格',
  `expire_date` datetime NOT NULL COMMENT '到期时间',
  `dic_id` int(10) NOT NULL COMMENT '供应商类型id',
  `business_scope` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` int(10) NOT NULL DEFAULT '1' COMMENT '所属性质1.个人 2.企业',
  `business_license` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `contacts` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `contact_phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `province` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `city` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `area` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` int(10) NOT NULL DEFAULT '0' COMMENT '状态 0.正常 1.到期 2.锁定',
  `recovery` int(10) NOT NULL DEFAULT '0' COMMENT '是否回收 0.否 1.是',
  `add_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `cumulative_balance` decimal(12,2) NOT NULL COMMENT '累计提现金额',
  `surplus_balance` decimal(12,2) NOT NULL COMMENT '剩余余额',
  `last_login_date` datetime DEFAULT NULL COMMENT '最后登录时间',
  `head_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供应商信息表';

-- ----------------------------
-- Records of lkt_supplier
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_supplier_account_log
-- ----------------------------
DROP TABLE IF EXISTS `lkt_supplier_account_log`;
CREATE TABLE `lkt_supplier_account_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `supplier_id` int(11) NOT NULL COMMENT '供应商id',
  `amount` decimal(12,2) NOT NULL COMMENT '金额',
  `account_money` decimal(12,2) NOT NULL COMMENT '供应商余额',
  `status` tinyint(3) NOT NULL DEFAULT '1' COMMENT '状态：1.入账 2.出账',
  `type` tinyint(3) NOT NULL DEFAULT '1' COMMENT '类型：1.订单 2.退款 3.提现',
  `addtime` timestamp NULL DEFAULT NULL COMMENT '时间',
  `remake` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供应商收支记录表';

-- ----------------------------
-- Records of lkt_supplier_account_log
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_supplier_bank_card
-- ----------------------------
DROP TABLE IF EXISTS `lkt_supplier_bank_card`;
CREATE TABLE `lkt_supplier_bank_card` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `store_id` int(11) NOT NULL COMMENT '商城ID',
  `supplier_id` int(11) NOT NULL COMMENT '供应商id',
  `Cardholder` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Bank_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `branch` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Bank_card_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认 1默认',
  `recycle` tinyint(1) NOT NULL DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供应商银行卡信息';

-- ----------------------------
-- Records of lkt_supplier_bank_card
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_supplier_brand
-- ----------------------------
DROP TABLE IF EXISTS `lkt_supplier_brand`;
CREATE TABLE `lkt_supplier_brand` (
  `brand_id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '品牌id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `brand_pic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `brand_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `brand_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `brand_y_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `producer` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '状态 0:启用 1:禁用',
  `brand_time` datetime DEFAULT NULL COMMENT '时间',
  `sort` int(10) DEFAULT '100',
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  `categories` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `supplier_id` int(10) DEFAULT NULL COMMENT '供应商id',
  `examine` tinyint(4) NOT NULL DEFAULT '0' COMMENT '审核状态 0.待审核 1.审核通过 2.不通过',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`brand_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品品牌表';

-- ----------------------------
-- Records of lkt_supplier_brand
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_supplier_config
-- ----------------------------
DROP TABLE IF EXISTS `lkt_supplier_config`;
CREATE TABLE `lkt_supplier_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(10) NOT NULL COMMENT '商城id',
  `min_recharge` decimal(12,2) DEFAULT NULL COMMENT '最小充值金额',
  `min_withdrawal` decimal(12,2) DEFAULT NULL COMMENT '最小提现金额',
  `max_withdrawal` decimal(12,2) DEFAULT NULL COMMENT '最大提现金额',
  `commission` decimal(12,2) DEFAULT NULL COMMENT '手续费',
  `wallet_unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_examine` int(11) NOT NULL DEFAULT '1' COMMENT '供应商商品是否需要审核 0.否 1.是',
  `withdrawal_instructions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供应商配置表';

-- ----------------------------
-- Records of lkt_supplier_config
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_supplier_configure
-- ----------------------------
DROP TABLE IF EXISTS `lkt_supplier_configure`;
CREATE TABLE `lkt_supplier_configure` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '配置id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `color` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `size` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `costprice` decimal(12,2) NOT NULL COMMENT '成本价',
  `price` decimal(12,2) NOT NULL COMMENT '出售价格',
  `yprice` decimal(12,2) NOT NULL COMMENT '供货价',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pid` int(11) NOT NULL COMMENT '商品id',
  `total_num` int(11) NOT NULL DEFAULT '0' COMMENT '总库存',
  `num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '剩余库存',
  `unit` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bar_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '状态 0:未开启砍价 1:开启砍价 2 上架 3 缺货 4下架',
  `attribute` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  `min_inventory` int(11) NOT NULL DEFAULT '10' COMMENT '产品预警值',
  `ctime` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `attribute_str` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `bargain_price` decimal(12,2) NOT NULL COMMENT '砍价价格',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id` (`id`) USING BTREE,
  KEY `pid` (`pid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品配置表';

-- ----------------------------
-- Records of lkt_supplier_configure
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_supplier_order_fright
-- ----------------------------
DROP TABLE IF EXISTS `lkt_supplier_order_fright`;
CREATE TABLE `lkt_supplier_order_fright` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(10) NOT NULL COMMENT '商城id',
  `sNo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `total_fright` decimal(12,0) NOT NULL COMMENT '总运费',
  `supplier_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_settlement` int(10) NOT NULL DEFAULT '0' COMMENT '是否结算 0.否 1.是',
  `add_date` datetime DEFAULT NULL COMMENT '创建时间',
  `detail_id` int(10) NOT NULL COMMENT '订单详情id',
  `freight` decimal(12,0) NOT NULL COMMENT '运费',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供应商订单运费结算';

-- ----------------------------
-- Records of lkt_supplier_order_fright
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_supplier_pro
-- ----------------------------
DROP TABLE IF EXISTS `lkt_supplier_pro`;
CREATE TABLE `lkt_supplier_pro` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '商品id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `product_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `commodity_type` tinyint(2) DEFAULT '0' COMMENT '商品类型 0.实物商品 1.虚拟商品',
  `product_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `subtitle` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `label` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `scan` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `product_class` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `imgurl` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `richList` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `upper_shelf_time` timestamp NULL DEFAULT NULL COMMENT '上架时间',
  `volume` int(12) NOT NULL DEFAULT '0' COMMENT '销量',
  `initial` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `s_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `num` int(11) NOT NULL DEFAULT '0' COMMENT '数量',
  `min_inventory` int(11) NOT NULL DEFAULT '10' COMMENT '库存预警',
  `status` tinyint(3) NOT NULL DEFAULT '1' COMMENT '状态 1:待上架 2:上架 3:下架 4.违规下架 5.断供\r\n\r\n',
  `brand_id` int(11) NOT NULL DEFAULT '0' COMMENT '品牌ID',
  `is_distribution` int(2) NOT NULL DEFAULT '0' COMMENT '是否为分销商品',
  `is_default_ratio` int(2) NOT NULL DEFAULT '0' COMMENT '是否默认比例',
  `keyword` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `weight` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `weight_unit` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `distributor_id` int(5) DEFAULT '0' COMMENT '分销等级id 购买就升级',
  `freight` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `is_zhekou` int(2) DEFAULT '0' COMMENT '是否开启会员',
  `separate_distribution` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `recycle` tinyint(4) NOT NULL DEFAULT '0' COMMENT '回收站 0.显示 1.回收',
  `gongyingshang` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_hexiao` tinyint(4) DEFAULT '0' COMMENT '是否支持线下核销:0--不支持　1--支持',
  `hxaddress` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `active` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mch_id` int(10) DEFAULT '0' COMMENT '商户ID',
  `mch_status` tinyint(2) NOT NULL DEFAULT '1' COMMENT '审核状态：1.待审核，2.审核通过，3.审核不通过，4.暂不审核',
  `refuse_reasons` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `search_num` int(11) NOT NULL DEFAULT '0' COMMENT '搜索次数',
  `show_adr` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `publisher` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_zixuan` tinyint(4) DEFAULT '1' COMMENT '是否自选 0.自选 1.不是自选',
  `commodity_str` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `source` tinyint(4) DEFAULT '2' COMMENT '来源 1.自选 2.上传',
  `comment_num` int(11) DEFAULT '0' COMMENT '评论数',
  `cover_map` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `class_sort` int(11) DEFAULT '0' COMMENT '分类排序',
  `display_position_sort` int(11) DEFAULT '0' COMMENT '显示位置排序',
  `lower_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `outage_time` datetime DEFAULT NULL COMMENT '断供时间',
  `total_num` int(11) DEFAULT '0' COMMENT '总库存',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品表';

-- ----------------------------
-- Records of lkt_supplier_pro
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_supplier_pro_class
-- ----------------------------
DROP TABLE IF EXISTS `lkt_supplier_pro_class`;
CREATE TABLE `lkt_supplier_pro_class` (
  `cid` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '分类id',
  `sid` int(11) NOT NULL COMMENT '上级id',
  `pname` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `english_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `img` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `level` int(11) NOT NULL COMMENT '级别',
  `sort` int(11) DEFAULT '100' COMMENT '排序',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `add_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `recycle` tinyint(4) DEFAULT '0' COMMENT '回收站 0.不回收 1.回收',
  `is_display` tinyint(3) DEFAULT '0' COMMENT '是否显示 0.不显示 1.显示',
  `supplier_id` int(10) DEFAULT NULL COMMENT '供应商id',
  `examine` tinyint(4) NOT NULL DEFAULT '0' COMMENT '审核状态 0.待审核 1.审核通过 2.不通过',
  `remark` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `real_cid` int(11) DEFAULT NULL COMMENT '实际商品分类id',
  PRIMARY KEY (`cid`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商品分类';

-- ----------------------------
-- Records of lkt_supplier_pro_class
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_supplier_stock
-- ----------------------------
DROP TABLE IF EXISTS `lkt_supplier_stock`;
CREATE TABLE `lkt_supplier_stock` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '商品id',
  `attribute_id` int(11) NOT NULL DEFAULT '0' COMMENT '属性id',
  `total_num` int(11) NOT NULL COMMENT '总库存',
  `flowing_num` int(11) NOT NULL DEFAULT '0' COMMENT '入库/出库',
  `type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '类型 0.入库 1.出库 2.预警',
  `user_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供应商库存记录表';

-- ----------------------------
-- Records of lkt_supplier_stock
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_supplier_withdraw
-- ----------------------------
DROP TABLE IF EXISTS `lkt_supplier_withdraw`;
CREATE TABLE `lkt_supplier_withdraw` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `supplier_id` int(11) NOT NULL DEFAULT '0' COMMENT '供应商id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bank_id` int(11) NOT NULL COMMENT '银行卡id',
  `money` decimal(12,2) NOT NULL COMMENT '提现金额',
  `z_money` decimal(12,2) NOT NULL COMMENT '剩余金额',
  `s_charge` decimal(12,2) NOT NULL COMMENT '手续费',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '状态 0：审核中 1：审核通过 2：拒绝',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '申请时间',
  `refuse` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `recovery` tinyint(4) DEFAULT '0' COMMENT '是否回收 0.未回收 1.回收',
  `voucher` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='供应商提现列表';

-- ----------------------------
-- Records of lkt_supplier_withdraw
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_system_bulletin_reading
-- ----------------------------
DROP TABLE IF EXISTS `lkt_system_bulletin_reading`;
CREATE TABLE `lkt_system_bulletin_reading` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `system_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='系统公告阅读表';

-- ----------------------------
-- Records of lkt_system_bulletin_reading
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_system_configuration
-- ----------------------------
DROP TABLE IF EXISTS `lkt_system_configuration`;
CREATE TABLE `lkt_system_configuration` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) DEFAULT '0' COMMENT '商户id',
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '登录页logo',
  `copyright_information` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '版权信息',
  `record_information` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备案信息',
  `link_to_landing_page` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '登录页友情链接',
  `add_time` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  `store_id_prefix` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '商城id前缀',
  `admin_default_portrait` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '默认头像设置',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='商城基本信息配置表';

-- ----------------------------
-- Records of lkt_system_configuration
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_system_message
-- ----------------------------
DROP TABLE IF EXISTS `lkt_system_message`;
CREATE TABLE `lkt_system_message` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `senderid` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `recipientid` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `title` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `time` datetime DEFAULT NULL COMMENT '时间',
  `type` int(2) NOT NULL DEFAULT '1' COMMENT '1未读  2 已读',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=409901 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='系统消息表';

-- ----------------------------
-- Records of lkt_system_message
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_system_tell
-- ----------------------------
DROP TABLE IF EXISTS `lkt_system_tell`;
CREATE TABLE `lkt_system_tell` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `store_id` int(11) DEFAULT '0' COMMENT '商城ID',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` tinyint(4) DEFAULT NULL COMMENT '公告类型: 1--系统维护  2--版本更新  3--普通公告',
  `startdate` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `enddate` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `timetype` tinyint(4) DEFAULT NULL COMMENT '时间类型: 1--区间时间  2--不限制',
  `add_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  `is_read` int(11) DEFAULT '0' COMMENT '是否已读取',
  `store_tell` int(4) NOT NULL DEFAULT '1' COMMENT '管理后台公告  1未选择 2选择',
  `user_tell` int(4) NOT NULL DEFAULT '1' COMMENT '用户公告  1未选择 2选择',
  `mch_tell` int(4) NOT NULL DEFAULT '1' COMMENT '商户公告  1未选择 2选择',
  `supplier_tell` int(4) NOT NULL DEFAULT '1' COMMENT '供应商公告  1未选择 2选择',
  `mch_son_tell` int(4) NOT NULL DEFAULT '1' COMMENT '门店端公告  1未选择 2选择',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='系统公告表';

-- ----------------------------
-- Records of lkt_system_tell
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_system_tell_user
-- ----------------------------
DROP TABLE IF EXISTS `lkt_system_tell_user`;
CREATE TABLE `lkt_system_tell_user` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `store_id` int(11) NOT NULL COMMENT '商城ID',
  `tell_id` int(11) NOT NULL COMMENT '公告id',
  `read_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `store_type` int(4) NOT NULL COMMENT '标记以读用户所在端 1微信小程序 , 2 h5, 11 app, 7 pc店铺, 6 pc商城 8 管理后台 9 PC门店核销, 10H5门店核销',
  `is_supplier` int(4) NOT NULL DEFAULT '0' COMMENT '是否为供应商  0不是  1是',
  `add_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户端用户标记公告以读记录表';

-- ----------------------------
-- Records of lkt_system_tell_user
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_third
-- ----------------------------
DROP TABLE IF EXISTS `lkt_third`;
CREATE TABLE `lkt_third` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `ticket` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ticket_time` timestamp NULL DEFAULT NULL COMMENT '凭证更新时间',
  `token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `token_expires` int(11) DEFAULT NULL COMMENT 'token过期时间戳',
  `appid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `appsecret` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `check_token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `encrypt_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `serve_domain` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `work_domain` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `redirect_url` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `mini_url` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `kefu_url` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `qr_code` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `H5` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `endurl` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='第三方授权表';

-- ----------------------------
-- Records of lkt_third
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_third_mapping
-- ----------------------------
DROP TABLE IF EXISTS `lkt_third_mapping`;
CREATE TABLE `lkt_third_mapping` (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `store_id` int(11) DEFAULT NULL COMMENT '商城id',
  `union_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `open_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` int(11) DEFAULT '0' COMMENT '0=微信 1=支付宝',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='第三方用户映射表';

-- ----------------------------
-- Records of lkt_third_mapping
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_third_mini_info
-- ----------------------------
DROP TABLE IF EXISTS `lkt_third_mini_info`;
CREATE TABLE `lkt_third_mini_info` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `nick_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `authorizer_appid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `authorizer_access_token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `authorizer_expires` int(11) unsigned DEFAULT NULL COMMENT '有效期（在授权的公众号或小程序具备API权限时，才有此返回值）',
  `authorizer_refresh_token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `update_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `func_info` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '授权给开发者的权限集列表',
  `expires_time` int(11) DEFAULT NULL COMMENT '过期时间戳',
  `company_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `head_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `verify_type_info` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `principal_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `business_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `qrcode_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `miniprograminfo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '根据这个字段判断是否为小程序类型授权',
  `store_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '商城id',
  `auditid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `review_mark` tinyint(2) DEFAULT '1' COMMENT '审核状态 1：未审核 2：审核中 3：审核失败 4：审核成功',
  `issue_mark` tinyint(2) DEFAULT '1' COMMENT '发布状态 1：未发布  2：发布失败 3：发布成功',
  `submit_time` datetime DEFAULT NULL COMMENT '审核提价时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='授权小程序信息表';

-- ----------------------------
-- Records of lkt_third_mini_info
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_third_template
-- ----------------------------
DROP TABLE IF EXISTS `lkt_third_template`;
CREATE TABLE `lkt_third_template` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `template_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `wx_desc` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `wx_version` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `wx_create_time` int(11) DEFAULT NULL COMMENT '添加进开放平台模板库时间戳',
  `lk_version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `lk_desc` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `img_url` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `store_id` int(11) DEFAULT NULL COMMENT '商城id',
  `trade_data` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_use` tinyint(2) DEFAULT '1' COMMENT '是否应用 0：不应用 1：应用',
  `update_time` datetime DEFAULT NULL COMMENT '模板更新时间',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='小程序模板表';

-- ----------------------------
-- Records of lkt_third_template
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_ui_navigation_bar
-- ----------------------------
DROP TABLE IF EXISTS `lkt_ui_navigation_bar`;
CREATE TABLE `lkt_ui_navigation_bar` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` tinyint(4) DEFAULT '0' COMMENT '跳转类型 1.分类 2.商品 3.店铺',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sort` int(11) DEFAULT '100' COMMENT '排序',
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  `isshow` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否显示',
  `is_login` tinyint(1) DEFAULT '1' COMMENT '是否需要登录 0 不需要登录 1 需要登录',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='UI导航栏表';

-- ----------------------------
-- Records of lkt_ui_navigation_bar
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_upload_set
-- ----------------------------
DROP TABLE IF EXISTS `lkt_upload_set`;
CREATE TABLE `lkt_upload_set` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `upserver` tinyint(4) NOT NULL DEFAULT '2' COMMENT '上传服务器:1,本地　2,阿里云 3,腾讯云 4,七牛云',
  `type` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `attr` char(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `attrvalue` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `upserver_idx` (`upserver`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=885 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='上传配置表';

-- ----------------------------
-- Records of lkt_upload_set
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user`;
CREATE TABLE `lkt_user` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户昵称',
  `cpc` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '86' COMMENT 'ITU电话代码',
  `country_num` int(11) DEFAULT '156' COMMENT '国家代码',
  `preferred_currency` int(11) DEFAULT '0' COMMENT '用户偏好货币id',
  `access_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '授权id',
  `access_key` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '授权密钥',
  `wx_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '微信id',
  `unionid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `wx_name` varbinary(150) DEFAULT NULL COMMENT '微信昵称',
  `gzh_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '公众号id',
  `zfb_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付宝id',
  `bd_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '百度id',
  `tt_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '头条id',
  `clientid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '推送客户端ID',
  `sex` int(11) NOT NULL DEFAULT '0' COMMENT '性别默认男 0:未知 1:男 2:女',
  `headimgurl` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '微信头像',
  `province` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '省',
  `city` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '市',
  `county` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '县',
  `detailed_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '详细地址',
  `money` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '金额',
  `score` bigint(24) unsigned DEFAULT '0' COMMENT '积分',
  `lock_score` int(11) unsigned DEFAULT '0' COMMENT '冻结的积分',
  `password` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '支付密码',
  `Register_data` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `e_mail` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '邮箱',
  `real_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '真实姓名',
  `mobile` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '手机号',
  `birthday` timestamp NULL DEFAULT NULL COMMENT '出生日期',
  `wechat_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '微信号',
  `address` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '地址',
  `Bank_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '银行名称',
  `Cardholder` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '持卡人',
  `Bank_card_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '银行卡号',
  `share_num` int(11) DEFAULT '0' COMMENT '分享次数',
  `Referee` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '推荐人',
  `access_token` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '访问令牌',
  `consumer_money` decimal(12,2) DEFAULT NULL COMMENT '消费金',
  `img_token` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '分享图片id',
  `zhanghao` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mima` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '密码',
  `source` tinyint(4) NOT NULL DEFAULT '1' COMMENT '来源 1.小程序 2.app 3.支付宝小程序 4.头条小程序 5.百度小程序 6.pc端 7.H5',
  `login_num` int(11) DEFAULT '0' COMMENT '登录次数',
  `verification_time` timestamp NULL DEFAULT NULL COMMENT '验证支付密码时间',
  `parameter` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '参数',
  `is_lock` tinyint(2) DEFAULT '0' COMMENT '是否冻结 0-不冻结 1-冻结',
  `last_time` timestamp NULL DEFAULT NULL COMMENT '最后一次登录时间',
  `grade` int(11) DEFAULT '0' COMMENT '会员级别 0--普通会员 ',
  `tui_id` char(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '会员推荐人id',
  `grade_add` timestamp NULL DEFAULT NULL COMMENT '充值会员等级时间',
  `grade_m` tinyint(4) DEFAULT NULL COMMENT '开通方式 1-包月 2-包季 3-包年',
  `grade_end` datetime DEFAULT NULL COMMENT '会员等级到期时间',
  `is_out` tinyint(2) DEFAULT '0' COMMENT '是否到期 0-未到期  1-已到期',
  `is_box` tinyint(2) DEFAULT '1' COMMENT '是否同意续费弹框 0-不同意 1 同意',
  `mch_token` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '店铺token',
  `lang` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '语言',
  `user_from_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '兵器设备用户ID',
  `is_default_value` tinyint(4) NOT NULL DEFAULT '1' COMMENT '是否使用的默认用户配置 1.是 2.否',
  `is_default_birthday` tinyint(4) NOT NULL DEFAULT '1' COMMENT '是否使用的默认日期配置 1.是 2.否',
  `token_living_pc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '主播pc的token',
  `fans_num` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `index_user_id` (`user_id`) USING BTREE,
  KEY `index_store_id` (`store_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=153 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='会员列表';

-- ----------------------------
-- Records of lkt_user
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user_address
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_address`;
CREATE TABLE `lkt_user_address` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '地址id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `tel` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sheng` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `city` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `quyu` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `address_xq` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `code` int(11) NOT NULL DEFAULT '0' COMMENT '邮政编号',
  `uid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_default` tinyint(2) NOT NULL DEFAULT '0' COMMENT '是否默认地址 1默认',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户收货地址表';

-- ----------------------------
-- Records of lkt_user_address
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user_authority
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_authority`;
CREATE TABLE `lkt_user_authority` (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `main_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` int(11) NOT NULL COMMENT '1=userId 2=admin_id',
  `role_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `create_id` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` datetime DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='通用菜单权限表';

-- ----------------------------
-- Records of lkt_user_authority
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user_bank_card
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_bank_card`;
CREATE TABLE `lkt_user_bank_card` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Cardholder` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `id_card` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Bank_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `branch` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Bank_card_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `is_default` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否默认地址 1默认',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户银行卡表';

-- ----------------------------
-- Records of lkt_user_bank_card
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user_collection
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_collection`;
CREATE TABLE `lkt_user_collection` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `p_id` int(11) DEFAULT NULL COMMENT '产品id',
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `mch_id` int(11) DEFAULT '0' COMMENT '店铺ID',
  `type` int(11) DEFAULT '1' COMMENT '收藏类型 1.普通收藏 2.积分商城收藏 3.竞拍',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='收藏表';

-- ----------------------------
-- Records of lkt_user_collection
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user_distribution
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_distribution`;
CREATE TABLE `lkt_user_distribution` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pid` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `level` int(11) NOT NULL COMMENT '等级',
  `lt` int(11) NOT NULL COMMENT 'lt',
  `rt` int(11) NOT NULL COMMENT 'rt',
  `uplevel` int(11) NOT NULL COMMENT '第几代',
  `add_date` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  `usets` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `commission` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '个人佣金',
  `onlyamount` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '累计消费',
  `allamount` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '销售业绩',
  `one_put` decimal(11,2) NOT NULL DEFAULT '0.00' COMMENT '个人进货奖励已经发放最大条件',
  `team_put` decimal(11,2) NOT NULL DEFAULT '0.00' COMMENT '团队业绩奖励已经发放最大',
  `accumulative` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '累计佣金',
  `tx_commission` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '可提现佣金',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='分销关联表';

-- ----------------------------
-- Records of lkt_user_distribution
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user_first
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_first`;
CREATE TABLE `lkt_user_first` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` char(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `grade_id` int(11) DEFAULT NULL COMMENT '会员等级id',
  `level` int(11) DEFAULT NULL COMMENT '首次开通会员级别',
  `store_id` int(11) DEFAULT NULL COMMENT '商城id',
  `is_use` tinyint(2) DEFAULT '0' COMMENT '是否使用了首次开通赠送商品券 0-未使用 1-已使用',
  `sNo` char(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `end_time` datetime DEFAULT NULL COMMENT '兑换券失效时间',
  `attr_id` int(11) DEFAULT NULL COMMENT '兑换商品的规格id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='等级会员首次开通表';

-- ----------------------------
-- Records of lkt_user_first
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user_footprint
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_footprint`;
CREATE TABLE `lkt_user_footprint` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `p_id` int(11) DEFAULT NULL COMMENT '产品id',
  `app_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5107 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='足迹表';

-- ----------------------------
-- Records of lkt_user_footprint
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user_grade
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_grade`;
CREATE TABLE `lkt_user_grade` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` char(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `rate` decimal(12,2) DEFAULT NULL COMMENT '打折率',
  `money` decimal(12,2) DEFAULT NULL COMMENT '包月金额',
  `store_id` int(11) unsigned DEFAULT NULL COMMENT '商城id',
  `money_j` decimal(12,2) DEFAULT NULL COMMENT '包季金额',
  `money_n` decimal(12,2) DEFAULT NULL COMMENT '包年金额',
  `remark` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `imgurl` char(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `imgurl_my` char(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `imgurl_s` char(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `level` int(11) DEFAULT NULL COMMENT '会员级别 普通-0   白银-1  黄金-2  黑金-3',
  `pro_id` int(11) DEFAULT NULL COMMENT '赠送商品id',
  `font_color` char(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `date_color` char(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='会员等级表';

-- ----------------------------
-- Records of lkt_user_grade
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user_role
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_role`;
CREATE TABLE `lkt_user_role` (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `main_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` int(11) NOT NULL COMMENT '1=门店id 2=店铺id 3=商城id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `text` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_date` datetime DEFAULT NULL COMMENT '创建时间',
  `update_date` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='通用菜单角色表';

-- ----------------------------
-- Records of lkt_user_role
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user_rule
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_rule`;
CREATE TABLE `lkt_user_rule` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `rate_now` decimal(12,2) DEFAULT NULL COMMENT '默认折率',
  `active` char(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `rule` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `wait` int(11) DEFAULT NULL COMMENT '有效期',
  `store_id` int(11) unsigned DEFAULT NULL COMMENT '商城id',
  `is_auto` tinyint(2) DEFAULT '1' COMMENT '是否开启自动续费 0-不开启 1-开启',
  `auto_time` int(11) unsigned DEFAULT NULL COMMENT '自动续费提前提醒时间（天）',
  `method` char(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_wallet` tinyint(2) DEFAULT '1' COMMENT '是否开启余额支付 0-不开启 1-开启',
  `upgrade` char(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_birthday` tinyint(2) DEFAULT '0' COMMENT '是否开启生日特权 0-不开启 1-开启',
  `bir_multiple` int(11) DEFAULT '1' COMMENT '生日特权积分倍数',
  `is_product` tinyint(2) DEFAULT '0' COMMENT '是否开启会员赠送商品 0-不开启 1-开启',
  `bond` decimal(12,2) NOT NULL COMMENT '提现保证金',
  `is_jifen` tinyint(2) DEFAULT '0' COMMENT '会员等比例积分 0-不开启 1-开启',
  `jifen_m` tinyint(2) DEFAULT '1' COMMENT '积分发送规则 0-付款后 1-收货后',
  `back` tinyint(2) DEFAULT NULL COMMENT '是否开启返现 0-不开启 1-开启',
  `back_scale` decimal(12,2) DEFAULT NULL COMMENT '返现比例',
  `poster` char(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_limit` tinyint(2) DEFAULT '0' COMMENT '是否开启推荐限制 0-不限制  1-限制',
  `level` int(11) DEFAULT NULL COMMENT '可以推荐的会员级别',
  `distribute_l` int(11) DEFAULT '0' COMMENT '可以参与分销的会员级别id',
  `valid` int(11) DEFAULT '7' COMMENT '增送商品的有效天数',
  `score` int(11) DEFAULT '0' COMMENT '积分过期设置',
  `bonus_points_shopping` tinyint(4) DEFAULT '0' COMMENT '购物赠送积分 0.未开启 \r\n\r\n1.开启',
  `proportion_of_gifts` int(11) DEFAULT '0' COMMENT '赠送比例',
  `release_time` tinyint(4) DEFAULT '1' COMMENT '发放时间 1.收货后  2.付款后',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='会员规则表';

-- ----------------------------
-- Records of lkt_user_rule
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_user_search
-- ----------------------------
DROP TABLE IF EXISTS `lkt_user_search`;
CREATE TABLE `lkt_user_search` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `token` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `keyword` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `add_date` datetime DEFAULT NULL COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户搜索表';

-- ----------------------------
-- Records of lkt_user_search
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_withdraw
-- ----------------------------
DROP TABLE IF EXISTS `lkt_withdraw`;
CREATE TABLE `lkt_withdraw` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `store_id` int(11) NOT NULL DEFAULT '0' COMMENT '商城id',
  `user_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户id',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '名称',
  `wx_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '微信id',
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '手机',
  `Bank_id` int(11) NOT NULL COMMENT '银行卡id',
  `money` decimal(12,2) NOT NULL COMMENT '提现金额',
  `z_money` decimal(12,2) NOT NULL COMMENT '剩余金额',
  `s_charge` decimal(12,2) NOT NULL COMMENT '手续费',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '状态 0：审核中 1：审核通过 2：拒绝',
  `add_date` datetime DEFAULT NULL COMMENT '申请时间',
  `refuse` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '拒绝原因',
  `is_mch` int(2) DEFAULT '0' COMMENT '是否是店铺提现',
  `txsno` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '提现订单号',
  `examine_date` timestamp NULL DEFAULT NULL COMMENT '提现审核时间',
  `withdraw_status` int(11) NOT NULL DEFAULT '1' COMMENT '提现类型 1银行卡  2微信余额  3贝宝余额',
  `wx_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '提现到微信余额提现状态：1进行中 2已完成 3提现失败',
  `recovery` tinyint(4) DEFAULT '0' COMMENT '是否回收 0.未回收 1.回收',
  `wx_open_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户openid',
  `wx_son` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '微信提现到零钱订单号',
  `wx_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户微信名称',
  `realname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户微信余额提现真实姓名',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '贝宝提现邮箱',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='提现列表';

-- ----------------------------
-- Records of lkt_withdraw
-- ----------------------------
-- ----------------------------
-- Table structure for lkt_write_record
-- ----------------------------
DROP TABLE IF EXISTS `lkt_write_record`;
CREATE TABLE `lkt_write_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `write_store_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `write_time` timestamp NULL DEFAULT NULL COMMENT '核销时间',
  `write_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `s_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `p_id` int(11) DEFAULT NULL COMMENT '订单详情id',
  `status` int(11) DEFAULT NULL COMMENT '核销状态 1.为已核销完 2.为退款状态中 3.为还有核销次数',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='核销记录表';

-- ----------------------------
-- Records of lkt_write_record
-- ----------------------------
